import { useEffect, useMemo, useRef, useState } from 'react';
import { humanize } from '@/lib/humanize';
import { ShapeIcon } from '@/lib/shapes';
import { MISSING, buildUnits, getDimension, unitValues } from '@/lib/analysis';

const CONFIG_TYPES = {
  type_of_artifact: 'typesOfArtifact',
  type_of_inquiry: 'typesOfInquiry',
};

const BASE_WIDTH = 120;
const GAP = 12;
const MAX_ONE_ROW = 6;
const MAX_SPLIT_TILES = 16;

const TILE_CHROME = 70;

let measureCtx = null;
function textWidth(text, font) {
  if (!measureCtx) measureCtx = document.createElement('canvas').getContext('2d');
  measureCtx.font = font;
  return measureCtx.measureText(text).width;
}

function minTileWidth(label, font) {
  const longest = Math.max(...String(label).split(/\s+/).map((w) => textWidth(w, font)));
  return Math.max(BASE_WIDTH, Math.ceil(longest + TILE_CHROME));
}

const weight = (t) => Math.max(t.count, 1);
const pxPerUnit = (row, width) =>
  (width - row.reduce((s, t) => s + t.minWidth, 0) - (row.length - 1) * GAP) / row.reduce((s, t) => s + weight(t), 0);
const byCount = (a, b) => b.count - a.count;

function layoutTiles(tiles, width) {
  const n = tiles.length;
  if (!width || n === 0) return null;
  if (n <= MAX_ONE_ROW) {
    const px = pxPerUnit(tiles, width);
    if (px > 0) return { rows: [[...tiles].sort(byCount)], px };
  }
  if (n < 2 || n > MAX_SPLIT_TILES) return null;
  let best = null;
  for (let mask = 1; mask < (1 << n) - 1; mask += 1) {
    if (mask & 1) continue;
    const rows = [[], []];
    tiles.forEach((t, i) => rows[(mask >> i) & 1].push(t));
    const px = Math.min(...rows.map((row) => pxPerUnit(row, width)));
    if (!best || px > best.px) best = { rows, px };
  }
  if (!best || best.px <= 0) return null;
  const rows = best.rows.map((row) => [...row].sort(byCount));
  const total = (row) => row.reduce((s, t) => s + t.count, 0);
  rows.sort((a, b) => total(b) - total(a));
  return { rows, px: best.px };
}

function useElementWidth(ref) {
  const [width, setWidth] = useState(0);
  useEffect(() => {
    if (!ref.current) return undefined;
    const observer = new ResizeObserver(([entry]) => setWidth(entry.contentRect.width));
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [ref]);
  return width;
}

/**
 * One tile per value of the chosen dimension, with the number of papers that
 * have it. Clicking a tile toggles that value as a filter. Dimensions with a
 * list in site.config.json (Type of Artifact, Type of Inquiry) use its labels,
 * descriptions and colours. Tile widths follow the counts (see layoutTiles).
 */
export default function CategoryOverview({
  dimKey, dimOptions, onDimChange, papers, config, colorFor, shapeFor = null, selected, onToggle, title, hint,
}) {
  const tiles = useMemo(() => {
    const dim = getDimension(dimKey);
    const counts = new Map();
    buildUnits(papers, 'paper').forEach((u) =>
      unitValues(u, dim).forEach((v) => v !== MISSING && counts.set(v, (counts.get(v) || 0) + 1))
    );
    const configured = config[CONFIG_TYPES[dimKey]];
    if (configured?.length) {
      return configured.map((t) => ({ id: t.id, label: t.label, description: t.description, color: t.color, count: counts.get(t.id) || 0 }));
    }
    return [...counts.entries()]
      .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
      .map(([id, count]) => ({ id, label: humanize(id), color: colorFor(dimKey, id), count }));
  }, [dimKey, papers, config, colorFor]);

  const gridRef = useRef(null);
  const width = useElementWidth(gridRef);
  const sized = useMemo(() => {
    if (!gridRef.current) return tiles.map((t) => ({ ...t, minWidth: BASE_WIDTH }));
    const family = getComputedStyle(gridRef.current).fontFamily;
    return tiles.map((t) => ({ ...t, minWidth: minTileWidth(t.label, `600 14px ${family}`) }));
  }, [tiles, width]);
  const layout = useMemo(() => layoutTiles(sized, width), [sized, width]);
  const rows = layout ? layout.rows : [sized];

  return (
    <section className="inquiry-overview">
      <div className="inquiry-overview__header inquiry-overview__header--with-select">
        <div>
          <h2 className="inquiry-overview__title">{title}</h2>
          {hint && <p className="inquiry-overview__hint">{hint}</p>}
        </div>
        <label className="ax-field category-overview__select">
          <span className="ax-field__label">Group by</span>
          <select className="ax-select" value={dimKey} onChange={(e) => onDimChange(e.target.value)}>
            {dimOptions.map((d) => <option key={d.key} value={d.key}>{d.label}</option>)}
          </select>
        </label>
      </div>
      <div className={`inquiry-overview__grid ${layout ? '' : 'inquiry-overview__grid--wrap'}`} ref={gridRef}>
        {rows.map((row, i) => (
          <div className="inquiry-overview__row" key={i}>
            {row.map((t) => {
              const isActive = selected.includes(t.id);
              const tileWidth = layout ? t.minWidth + weight(t) * layout.px : undefined;
              return (
                <button
                  key={t.id}
                  type="button"
                  className={`inquiry-card ${isActive ? 'inquiry-card--active' : ''}`}
                  style={{ '--inquiry-color': t.color || 'var(--accent)', minWidth: t.minWidth, ...(tileWidth && { width: tileWidth }) }}
                  onClick={() => onToggle(t.id)}
                  aria-pressed={isActive}
                  title={t.description ? `${t.label}: ${t.description}` : t.label}
                >
                  {shapeFor && shapeFor(dimKey, t.id) ? (
                    <span className="inquiry-card__swatch inquiry-card__swatch--shape">
                      <ShapeIcon shape={shapeFor(dimKey, t.id)} color={t.color || 'var(--accent)'} />
                    </span>
                  ) : (
                    <span className="inquiry-card__swatch" />
                  )}
                  <span className="inquiry-card__label">{t.label}</span>
                  <span className="inquiry-card__count">{t.count}</span>
                  {t.description && <span className="inquiry-card__description">{t.description}</span>}
                </button>
              );
            })}
          </div>
        ))}
      </div>
    </section>
  );
}
