import { useMemo, useState } from 'react';
import { proposePapers } from '@/lib/proposal';

const changedSinceProposed = (p) => Boolean(p._proposedAt && p._editedAt && p._editedAt > p._proposedAt);

function proposedLabel(p) {
  if (!p._proposedAt) return null;
  const date = new Date(p._proposedAt).toLocaleDateString();
  return changedSinceProposed(p) ? `proposed ${date}, changed since` : `proposed ${date}`;
}

export default function ProposePapersModal({ papers, initialKeys = null, onClose, onProposed }) {
  const entries = useMemo(() => (papers || []).filter((p) => p._userAdded), [papers]);
  const [selected, setSelected] = useState(() => new Set(
    initialKeys?.length
      ? initialKeys
      : entries.filter((p) => !p._proposedAt || changedSinceProposed(p)).map((p) => p._userKey)
  ));
  const chosen = entries.filter((p) => selected.has(p._userKey));
  const allSelected = entries.length > 0 && chosen.length === entries.length;

  const toggle = (key) => setSelected((prev) => {
    const next = new Set(prev);
    if (next.has(key)) next.delete(key); else next.add(key);
    return next;
  });

  const handlePropose = () => {
    if (chosen.length === 0) return;
    proposePapers(chosen).then(() => onProposed?.());
    onClose();
  };

  return (
    <>
      <div className="modal__backdrop" onClick={onClose} />
      <div className="modal" role="dialog" aria-labelledby="propose-papers-title">
        <div className="modal__header">
          <h2 id="propose-papers-title">Propose Your Papers</h2>
          <button className="paper-panel__close" onClick={onClose} aria-label="Close">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          </button>
        </div>
        <div className="modal__body">
          {entries.length === 0 ? (
            <p className="add-paper__hint">You have not added any papers yet.</p>
          ) : (
            <>
              <p className="add-paper__hint">
                Choose which of your papers to propose for the shared dataset. One paper opens a pre-filled GitHub issue.
                Several papers are saved together in one JSON file, which you attach to the pre-filled issue.
              </p>
              <label className="add-paper__added-item add-paper__select-all">
                <input
                  type="checkbox"
                  checked={allSelected}
                  onChange={() => setSelected(allSelected ? new Set() : new Set(entries.map((p) => p._userKey)))}
                />
                <span>Select all ({entries.length})</span>
              </label>
              <ul className="add-paper__added">
                {entries.map((p) => (
                  <li key={p._userKey}>
                    <label className="add-paper__added-item">
                      <input type="checkbox" checked={selected.has(p._userKey)} onChange={() => toggle(p._userKey)} />
                      <span>
                        {p.metadata.title || '(untitled)'}
                        {proposedLabel(p) && <span className="add-paper__added-meta"> · {proposedLabel(p)}</span>}
                      </span>
                    </label>
                  </li>
                ))}
              </ul>
            </>
          )}
          <div className="modal__actions">
            <button className="btn btn--ghost" onClick={onClose}>Cancel</button>
            <button className="btn btn--primary" onClick={handlePropose} disabled={chosen.length === 0}>
              Propose {chosen.length} for shared dataset →
            </button>
          </div>
        </div>
      </div>
    </>
  );
}
