
const STIFFNESS = 0.12;
const DAMPING = 0.22;
const MAX_V = 1.8;

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

export function attachBubbleMotion(root, { selector, radius = 160, maxPull = 9, mass, anchor } = {}) {
  if (!root || typeof window === 'undefined') return () => {};
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return () => {};

  const springs = new WeakMap();
  let cursor = null;
  let raf = null;

  const springOf = (el) => {
    let s = springs.get(el);
    if (!s) {
      const m = mass ? mass(el) : Number(el.dataset?.mass) || 1;
      s = { x: 0, y: 0, vx: 0, vy: 0, m: Number.isFinite(m) ? m : 1 };
      springs.set(el, s);
    }
    return s;
  };

  const frame = () => {
    const els = root.querySelectorAll(selector);

    const plan = [];
    els.forEach((el) => {
      const s = springOf(el);
      let tx = 0;
      let ty = 0;
      if (cursor) {
        const b = ((anchor && el.querySelector(anchor)) || el).getBoundingClientRect();
        const dx = cursor.x - (b.left + b.width / 2 - s.x);
        const dy = cursor.y - (b.top + b.height / 2 - s.y);
        const dist = Math.hypot(dx, dy);
        if (dist > 0.5 && dist < radius) {
          const falloff = (1 - dist / radius) ** 2;
          const pull = Math.min(maxPull * falloff * s.m, dist * 0.4);
          tx = (dx / dist) * pull;
          ty = (dy / dist) * pull;
        }
      }
      plan.push([el, s, tx, ty]);
    });

    let moving = false;
    plan.forEach(([el, s, tx, ty]) => {
      s.vx = clamp(s.vx + STIFFNESS * (tx - s.x) - DAMPING * s.vx, -MAX_V * 2, MAX_V * 2);
      s.vy = clamp(s.vy + STIFFNESS * (ty - s.y) - DAMPING * s.vy, -MAX_V * 2, MAX_V * 2);
      s.x += s.vx;
      s.y += s.vy;
      if (Math.abs(s.x - tx) + Math.abs(s.y - ty) + Math.abs(s.vx) + Math.abs(s.vy) < 0.02) {
        s.x = tx;
        s.y = ty;
        s.vx = 0;
        s.vy = 0;
      } else {
        moving = true;
      }
      el.style.translate = s.x || s.y ? `${s.x.toFixed(2)}px ${s.y.toFixed(2)}px` : '';
    });

    raf = moving ? requestAnimationFrame(frame) : null;
  };

  const wake = () => {
    if (!raf) raf = requestAnimationFrame(frame);
  };

  const onPointerMove = (e) => {
    if (e.pointerType === 'touch') return;
    cursor = { x: e.clientX, y: e.clientY };
    wake();
  };
  const onPointerLeave = () => {
    cursor = null;
    wake();
  };

  root.addEventListener('pointermove', onPointerMove, { passive: true });
  root.addEventListener('pointerleave', onPointerLeave, { passive: true });

  return () => {
    root.removeEventListener('pointermove', onPointerMove);
    root.removeEventListener('pointerleave', onPointerLeave);
    if (raf) cancelAnimationFrame(raf);
    root.querySelectorAll(selector).forEach((el) => { el.style.translate = ''; });
  };
}
