import { useEffect, useState } from 'react';
import { getDataSource, loadPapers } from '@/lib/data';
import { codingCounts, downloadReview, restartSite } from '@/lib/review';
import { clearWorkspace, loadWorkspace, setWorkspaceActive } from '@/lib/workspace';
import { useCoding } from '@/lib/codingState';

const DISMISS_KEY = 'ariadne-lit:review-banner-dismissed';
const plural = (n, one, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;

function readDismissed() {
  try {
    return sessionStorage.getItem(DISMISS_KEY) === '1';
  } catch {
    return false;
  }
}

function writeDismissed() {
  try {
    sessionStorage.setItem(DISMISS_KEY, '1');
  } catch {
    // Without session storage the bar comes back on the next page.
  }
}

const savedOn = (iso) => {
  const d = iso ? new Date(iso) : null;
  return d && !Number.isNaN(d.getTime()) ? d.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : null;
};

/**
 * The bar under the header about the visitor's own review:
 *  - while it is shown: its name and coding progress, Code (the next paper
 *    not fully coded), Download, Back to the Published Dataset
 *    and Delete;
 *  - while the published dataset is shown and a review is stored: Show My
 *    Review (can be hidden for the session);
 *  - when the review could not be shown at startup: why.
 */
export default function ReviewBanner() {
  const source = getDataSource();
  const active = source.kind === 'workspace';
  const [counts, setCounts] = useState(null);
  const [stored, setStored] = useState(null);
  const [dismissed, setDismissed] = useState(readDismissed);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const { openCoding } = useCoding();

  useEffect(() => {
    if (active) loadPapers().then((papers) => setCounts({ total: papers.length, ...codingCounts(papers) }));
    else loadWorkspace().then(setStored);
  }, [active]);

  const act = async (action) => {
    setBusy(true);
    setError(null);
    try {
      await action();
      restartSite();
    } catch (e) {
      setError(e.message);
      setBusy(false);
    }
  };

  const remove = () => {
    const name = active ? source.name : stored?.name;
    if (!window.confirm(`Delete your review "${name}" from this browser? Download it first to keep a copy.`)) return;
    act(clearWorkspace);
  };

  if (active) {
    const date = savedOn(source.savedAt);
    return (
      <div className="review-banner" role="region" aria-label="Your review">
        <p className="review-banner__text">
          <span className="review-banner__eyebrow">Your review</span>
          <strong>{source.name}</strong>
          {counts && (
            <span className="review-banner__meta">
              {plural(counts.total, 'paper')} · {counts.coded} fully coded
              {counts.uncoded > 0 && ` · ${counts.uncoded} not fully coded`}
              {counts.problems > 0 && ` · ${counts.problems} with problems`}
              {date && ` · saved ${date}`}
            </span>
          )}
        </p>
        <div className="review-banner__actions">
          {counts && counts.total > 0 && (
            <button type="button" className="btn btn--primary btn--sm" disabled={busy} onClick={() => openCoding()}>
              {counts.coded < counts.total ? 'Code Next Uncoded' : 'Code Papers'}
            </button>
          )}
          <button type="button" className="btn btn--secondary btn--sm" disabled={busy}
            onClick={() => downloadReview(source)} title="Save the schema and papers as one file, to keep or share">
            Download
          </button>
          <button type="button" className="btn btn--secondary btn--sm" disabled={busy} onClick={() => act(() => setWorkspaceActive(false))}>
            Back to the Published Dataset
          </button>
          <button type="button" className="btn btn--ghost btn--sm" disabled={busy} onClick={remove}>Delete</button>
        </div>
        {error && <p className="add-paper__error review-banner__error" role="alert">{error}</p>}
      </div>
    );
  }

  if (source.reviewer) {
    return (
      <div className="review-banner" role="status" aria-label="Reviewer access">
        <p className="review-banner__text">
          <span className="review-banner__eyebrow">Reviewer access</span>
          The full dataset is shown, including all paper titles. Please do not share the reviewer link.
        </p>
      </div>
    );
  }

  if (source.notice) {
    return (
      <div className="review-banner review-banner--warning" role="alert">
        <p className="review-banner__text">{source.notice}</p>
        {stored && (
          <div className="review-banner__actions">
            <button type="button" className="btn btn--secondary btn--sm" disabled={busy}
              onClick={() => downloadReview(stored)}>Download It</button>
            {stored.active && (
              <button type="button" className="btn btn--secondary btn--sm" disabled={busy}
                onClick={() => act(() => setWorkspaceActive(false))} title="Stop trying to show it when the site starts">
                Keep It Switched Off
              </button>
            )}
            <button type="button" className="btn btn--ghost btn--sm" disabled={busy} onClick={remove}>Delete It</button>
          </div>
        )}
        {error && <p className="add-paper__error review-banner__error" role="alert">{error}</p>}
      </div>
    );
  }

  if (stored && !dismissed) {
    return (
      <div className="review-banner review-banner--quiet" role="region" aria-label="Your stored review">
        <p className="review-banner__text">
          Your review <strong>{stored.name}</strong> ({plural(stored.papers.length, 'paper')}) is stored in this browser.
        </p>
        <div className="review-banner__actions">
          <button type="button" className="btn btn--primary btn--sm" disabled={busy} onClick={() => act(() => setWorkspaceActive(true))}>
            Show My Review
          </button>
          <button type="button" className="btn btn--ghost btn--sm" onClick={() => { writeDismissed(); setDismissed(true); }}>
            Hide
          </button>
        </div>
        {error && <p className="add-paper__error review-banner__error" role="alert">{error}</p>}
      </div>
    );
  }

  return null;
}
