import { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { createLandscape } from '@/viz/landscape';

/**
 * papers: every paper (fixes the order of the tracks and each dot's jitter).
 * highlightIds: Set of paper ids that match the current search/filters, or
 *   null for "all" — only these are drawn, and the axes fit them.
 * colorOf: (paper) => colour for its dot.
 */
export default function LandscapeVisualization({ papers, highlightIds = null, colorOf, shapeOf = null }) {
  const containerRef = useRef(null);
  const instanceRef = useRef(null);
  const latest = useRef({ highlightIds, colorOf });
  latest.current = { highlightIds, colorOf };
  const navigate = useNavigate();

  useEffect(() => {
    if (!containerRef.current || papers.length === 0) return undefined;

    const build = () => createLandscape(containerRef.current, papers, {
      colorOf: latest.current.colorOf,
      shapeOf,
      highlightIds: latest.current.highlightIds,
      onPaperClick: (id) => navigate(`/papers/${id}`),
    });
    instanceRef.current = build();

    let lastWidth = containerRef.current.clientWidth;
    let frame = 0;
    const rebuild = () => {
      instanceRef.current?.destroy();
      instanceRef.current = build();
    };
    const observer = new ResizeObserver(([entry]) => {
      const w = Math.round(entry.contentRect.width);
      if (w === lastWidth) return;
      lastWidth = w;
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(rebuild);
    });
    observer.observe(containerRef.current);
    window.addEventListener('resize', rebuild);

    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
      window.removeEventListener('resize', rebuild);
      instanceRef.current?.destroy();
      instanceRef.current = null;
    };
  }, [papers, highlightIds, shapeOf, navigate]);

  useEffect(() => {
    instanceRef.current?.setColors(colorOf);
  }, [colorOf]);

  return <div className="landscape-viz" ref={containerRef} />;
}
