import { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Header from '@/components/Header';
import SchemaPanel from '@/components/SchemaPanel';
import { getDataSource, loadPapers, loadConfig } from '@/lib/data';
import { codingCounts } from '@/lib/review';
import { getArtifactTypes, isAnonymized } from '@/lib/filters';
import { humanize } from '@/lib/humanize';
import { makeShapeFor } from '@/lib/colors';
import { ShapeIcon, useShapes } from '@/lib/shapes';
import { compareTimelineRows, timelineRowKey, timelineRowOf, yearOf } from '@/lib/roles';
import { DIMENSIONS } from '@/lib/analysis';

const BASE_PATH = import.meta.env.BASE_URL || '/';

const plural = (n, one, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;

function ConfigText({ text, as: Tag = 'p', className = '' }) {
  if (!text) return null;
  const todo = /^\s*TODO\b/i.test(text);
  return <Tag className={`${className} ${todo ? 'about-todo' : ''}`.trim()}>{text}</Tag>;
}

function CopyButton({ text }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch {
      setCopied(false);
    }
  };
  return (
    <button type="button" className="btn btn--secondary btn--sm about-copy" onClick={copy} aria-live="polite">
      {copied ? 'Copied' : 'Copy BibTeX'}
    </button>
  );
}

export default function AboutPage() {
  const [papers, setPapers] = useState(null);
  const [config, setConfig] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    Promise.all([loadPapers(), loadConfig()]).then(([p, c]) => {
      setPapers(p);
      setConfig(c);
    });
  }, []);

  const { shapes } = useShapes();
  const shapeFor = useMemo(() => (shapes && config ? makeShapeFor(config, papers) : null), [shapes, config, papers]);

  const stats = useMemo(() => {
    if (!papers) return null;
    const typeCounts = {};
    papers.forEach((p) => getArtifactTypes(p).forEach((t) => { typeCounts[t] = (typeCounts[t] || 0) + 1; }));
    const years = papers.map(yearOf).filter(Boolean);
    const tracks = [...new Set(papers.map(timelineRowOf).filter(Boolean))].sort(compareTimelineRows);
    const anonymized = papers.filter(isAnonymized).length;
    return {
      papers: papers.length,
      yearFrom: years.length ? Math.min(...years) : null,
      yearTo: years.length ? Math.max(...years) : null,
      tracks,
      identified: papers.length - anonymized,
      anonymized,
      typeCounts,
      coding: getDataSource().kind === 'workspace' ? codingCounts(papers) : null,
    };
  }, [papers]);

  if (!papers || !config) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  const about = config.about || {};
  const rowLabel = humanize(timelineRowKey() || 'track');
  // The dimensions marked "about.dimension" in the schema: first in the order
  // of about.dimensions in site.config.json, whose descriptions take
  // precedence, then the rest with the schema's description. Type of Artifact
  // has its own cards above when the config lists the types.
  const configDims = new Map((about.dimensions || []).map((d) => [d.key, d]));
  const listed = DIMENSIONS.filter((d) => d.uses.includes('about.dimension'));
  const otherDimensions = [
    ...(about.dimensions || []).map((c) => listed.find((d) => d.key === c.key)).filter(Boolean),
    ...listed.filter((d) => !configDims.has(d.key)),
  ]
    .filter((d) => !(d.key === 'type_of_artifact' && (config.typesOfArtifact || []).length > 0))
    .map((d) => ({ key: d.key, description: configDims.get(d.key)?.description || d.description }));
  const license = about.license || {};
  const navLabel = (path) => (config.navigation || []).find((n) => n.path === path)?.label || path;
  const openType = (id) => navigate({ pathname: '/', search: `?f_type_of_artifact=${encodeURIComponent(id)}` });

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content about-page">
        <header className="about-hero">
          <h1>{about.title || 'About'}</h1>
          <ConfigText text={about.introduction} className="about-page__intro" />
        </header>

        <section className="about-block" aria-labelledby="about-glance">
          <h2 id="about-glance" className="detail-section__title">At a Glance</h2>
          <div className="about-stats">
            <div className="about-stat"><span className="about-stat__value">{stats.papers}</span><span className="about-stat__label">Papers</span></div>
            {timelineRowKey() && (
              <div className="about-stat">
                <span className="about-stat__value">{stats.tracks.length}</span>
                <span className="about-stat__label">{rowLabel}{stats.tracks.length === 1 ? '' : 's'}{stats.tracks.length ? `: ${stats.tracks.join(', ')}` : ''}</span>
              </div>
            )}
            {stats.coding ? (
              <div className="about-stat">
                <span className="about-stat__value">{stats.coding.coded} <span className="about-stat__of">/ {stats.papers}</span></span>
                <span className="about-stat__label">
                  Fully coded{stats.coding.problems > 0 && ` · ${stats.coding.problems} with problems`}
                </span>
              </div>
            ) : (
              <div className="about-stat">
                <span className="about-stat__value">{stats.identified} <span className="about-stat__of">/ {stats.papers}</span></span>
                <span className="about-stat__label">Listed by title · {stats.anonymized} anonymized</span>
              </div>
            )}
            <div className="about-stat">
              <span className="about-stat__value">{stats.yearFrom ? `${stats.yearFrom}–${stats.yearTo}` : '—'}</span>
              <span className="about-stat__label">Years</span>
            </div>
          </div>
          <ConfigText text={about.dataVersion} className="about-page__version" />
        </section>

        {(about.pages || []).length > 0 && (
          <section className="about-block" aria-labelledby="about-pages">
            <h2 id="about-pages" className="detail-section__title">Using the Site</h2>
            <div className="about-cards">
              {about.pages.map((pg) => (
                <Link key={pg.path} to={pg.path} className="about-card">
                  <span className="about-card__title">{navLabel(pg.path)} →</span>
                  <span className="about-card__text">{pg.description}</span>
                </Link>
              ))}
            </div>
            {about.addingPapers && (
              <>
                <h3 className="about-subtitle">Adding Papers from Zotero</h3>
                <p className="about-text">{about.addingPapers}</p>
              </>
            )}
          </section>
        )}

        <section className="about-block" aria-labelledby="about-scheme">
          <h2 id="about-scheme" className="detail-section__title">Coding Scheme</h2>
          <p className="about-text">
            Every paper is described with the same coded dimensions. Each paper can have several codes per
            dimension.
          </p>

          {(config.typesOfArtifact || []).length > 0 && (
            <>
              <h3 className="about-subtitle">Types of Artifact</h3>
              <p className="about-text about-text--muted">Click a type to see its papers on {navLabel('/')}.</p>
              <div className="about-types">
                {config.typesOfArtifact.map((t) => (
                  <button key={t.id} type="button" className="about-type" style={{ '--inquiry-color': t.color }}
                    onClick={() => openType(t.id)} title={`Show papers with ${t.label}`}>
                    <span className="about-type__head">
                      {shapeFor && shapeFor('type_of_artifact', t.id) ? (
                        <span className="inquiry-card__swatch inquiry-card__swatch--shape">
                          <ShapeIcon shape={shapeFor('type_of_artifact', t.id)} color={t.color} />
                        </span>
                      ) : (
                        <span className="inquiry-card__swatch" />
                      )}
                      <strong>{t.label}</strong>
                      <span className="about-type__count">{plural(stats.typeCounts[t.id] || 0, 'paper')}</span>
                    </span>
                    {t.description && <span className="about-type__text">{t.description}</span>}
                  </button>
                ))}
              </div>
            </>
          )}

          {otherDimensions.length > 0 && (
            <>
              <h3 className="about-subtitle">Other Dimensions</h3>
              <dl className="about-dims">
                {otherDimensions.map((d) => (
                  <div key={d.key} className="about-dims__row">
                    <dt>{humanize(d.key)}</dt>
                    <dd>{d.description}</dd>
                  </div>
                ))}
              </dl>
            </>
          )}

          {about.ownReview && (
            <>
              <h3 className="about-subtitle">{about.ownReview.title || 'Your Own Review'}</h3>
              <ConfigText text={about.ownReview.introduction} className="about-text" />
              {(about.ownReview.steps || []).length > 0 && (
                <ol className="about-text about-steps">
                  {about.ownReview.steps.map((step) => <li key={step}>{step}</li>)}
                </ol>
              )}
            </>
          )}

          {about.schemaFile && (
            <>
              <h3 className="about-subtitle">Schema and Views</h3>
              <SchemaPanel schemaUrl={`${BASE_PATH}data/${about.schemaFile}`} schemaFile={about.schemaFile}
                review={getDataSource().kind === 'workspace' ? getDataSource() : null} />
            </>
          )}
        </section>

        {(about.method || []).length > 0 && (
          <section className="about-block" aria-labelledby="about-method">
            <h2 id="about-method" className="detail-section__title">How the Data of This Demonstration Was Made</h2>
            <dl className="about-method">
              {about.method.map((m) => (
                <div key={m.title} className="about-method__row">
                  <dt>{m.title}</dt>
                  <ConfigText text={m.content} as="dd" />
                </div>
              ))}
            </dl>
          </section>
        )}

        <section className="about-block" aria-labelledby="about-cite">
          <h2 id="about-cite" className="detail-section__title">{license.citation ? 'Cite, License & Contact' : 'License & Contact'}</h2>

          {license.citation && (
            <>
              <h3 className="about-subtitle">How to Cite</h3>
              {license.citation.text && <p className="about-text">{license.citation.text}</p>}
              {license.citation.bibtex && (
                <div className="about-bibtex">
                  <CopyButton text={license.citation.bibtex} />
                  <pre className="about-page__citation"><code>{license.citation.bibtex}</code></pre>
                </div>
              )}
            </>
          )}

          {license.text && (
            <>
              <h3 className="about-subtitle">License</h3>
              <p className="about-text">
                {license.text}{' '}
                <a className="about-page__license-link" href={license.url} target="_blank" rel="noopener noreferrer license">
                  {license.fullName || license.name}
                </a>
              </p>
            </>
          )}

          {license.funding?.text && (
            <>
              <h3 className="about-subtitle">Funding</h3>
              <p className="about-text">{license.funding.text}</p>
            </>
          )}

          {license.history?.text && (
            <>
              <h3 className="about-subtitle">Earlier Version</h3>
              <p className="about-text">
                {license.history.text}{' '}
                {license.history.url && (
                  <a className="about-page__license-link" href={license.history.url} target="_blank" rel="noopener noreferrer">
                    {license.history.linkLabel || license.history.url}
                  </a>
                )}
              </p>
            </>
          )}

          <h3 className="about-subtitle">Contribute &amp; Contact</h3>
          {about.contribute && <p className="about-text">{about.contribute}</p>}
          {license.reference && (
            <p className="about-text">
              {license.reference.text}{' '}
              {license.reference.serviceUrl && (
                <a className="about-page__license-link" href={license.reference.serviceUrl} target="_blank" rel="noopener noreferrer">
                  {license.reference.serviceLabel || license.reference.serviceUrl}
                </a>
              )}
              {license.reference.contactEmail && (
                <>
                  {' · '}
                  <a className="about-page__license-link" href={`mailto:${license.reference.contactEmail}`}>
                    {license.reference.contactName || license.reference.contactEmail}
                  </a>
                </>
              )}
            </p>
          )}
        </section>
      </main>
    </div>
  );
}
