import { useEffect, useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Header from '@/components/Header';
import ArtifactCard from '@/components/ArtifactCard';
import { loadPapers, loadConfig, getPaperById } from '@/lib/data';
import { humanize } from '@/lib/humanize';
import { DETAIL } from '@/lib/detail';
import { keywordsOf, timelineRowKey, timelineRowOf, yearOf } from '@/lib/roles';

// Yes/no rows read "No" when not coded; lists are humanized and joined.
function cellOf(row, v) {
  if (row.kind === 'boolean') return v ? 'Yes' : 'No';
  if (Array.isArray(v) || v === undefined || v === null) return (v || []).map(humanize).join(', ');
  return String(v);
}

function Row({ label, cells }) {
  return (
    <tr>
      <td className="compare-table__label">{label}</td>
      {cells.map((cell, i) => (
        <td key={i} className="compare-table__cell">{cell ?? '—'}</td>
      ))}
    </tr>
  );
}

export default function ComparePage() {
  const [params] = useSearchParams();
  const navigate = useNavigate();
  const [papers, setPapers] = useState(null);
  const [config, setConfig] = useState(null);

  useEffect(() => {
    Promise.all([loadPapers(), loadConfig()]).then(([p, c]) => {
      setPapers(p);
      setConfig(c);
    });
  }, []);

  if (!papers || !config) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  const ids = (params.get('ids') || '').split(',').filter(Boolean);
  const selected = ids.map((id) => getPaperById(papers, id)).filter(Boolean);

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content">
        <button className="btn btn--ghost paper-detail__back" onClick={() => navigate('/')}>← Back to Overview</button>
        <h1>Compare Papers</h1>

        {selected.length < 2 ? (
          <div className="empty-state">
            <h3>Select at least 2 papers</h3>
            <p>Go back to the Papers list, turn on compare mode, and pick two or more papers.</p>
          </div>
        ) : (
          <>
            <div className="compare-table-wrap">
              <table className="compare-table">
                <thead>
                  <tr>
                    <th className="compare-table__label">Field</th>
                    {selected.map((p) => (
                      <th key={p._id} className="compare-table__cell compare-table__cell--header">{p.metadata.title}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  <Row label="Authors" cells={selected.map((p) => p.metadata.authors?.join(', '))} />
                  <Row label="Year" cells={selected.map(yearOf)} />
                  {timelineRowKey() && <Row label={humanize(timelineRowKey())} cells={selected.map(timelineRowOf)} />}
                  {DETAIL.compareRows.map((r) => (
                    <Row key={r.path} label={r.label} cells={selected.map((p) => cellOf(r, r.read(p)))} />
                  ))}
                  <Row label={humanize('keywords')} cells={selected.map((p) => keywordsOf(p).join(', '))} />
                </tbody>
              </table>
            </div>

            {selected.map((p) => (
              <section className="detail-section" key={p._id}>
                <h2 className="detail-section__title">{p.metadata.title} — {DETAIL.artifacts.title}</h2>
                <div className="artifact-grid">
                  {(p.contribution.artifacts || []).map((artifact, i) => (
                    <ArtifactCard key={i} artifact={artifact} />
                  ))}
                </div>
              </section>
            ))}
          </>
        )}
      </main>
    </div>
  );
}
