import { humanize } from '@/lib/humanize';
import { isOtherId } from '@/lib/formLists';

/** ChipSelect: a labeled group of toggle chips, shared by Add Paper and
 * the coding form. `selected` is always the
 * form's array field; whether clicking a chip adds/removes it (multi) or
 * replaces the whole selection (single) is up to whatever `onToggle` does.
 * With `other`, choosing the "Other" chip opens a required text field for
 * the name of that other value; `other.id` names that field when the same
 * label appears more than once (e.g. once per artifact); `other.autoFocus`
 * false keeps the cursor where it is when the field shows up. */
export default function ChipSelect({ label, hint, options, selected, onToggle, colorOf, other }) {
  const otherSelected = Boolean(other) && selected.some(isOtherId);
  const otherInvalid = otherSelected && other.showError && !other.value.trim();
  const otherInputId = other?.id || `add-paper-other-${label.replace(/\W+/g, '-').toLowerCase()}`;
  return (
    <div className="add-paper__field">
      <label className="filters-panel__label">{label}</label>
      {hint && <p className="add-paper__hint">{hint}</p>}
      <div className="filters-panel__chips">
        {options.map((opt) => {
          const id = typeof opt === 'string' ? opt : opt.id;
          const text = typeof opt === 'string' ? humanize(opt) : opt.label;
          const active = selected.includes(id);
          const color = colorOf?.(id);
          return (
            <button
              key={id}
              type="button"
              className={`filter-chip ${active ? 'filter-chip--active' : ''}`}
              style={active && color ? { borderColor: color, background: `color-mix(in srgb, ${color} 15%, transparent)`, color } : undefined}
              onClick={() => onToggle(id)}
              aria-pressed={active}
            >
              {text}
            </button>
          );
        })}
      </div>
      {otherSelected && (
        <div className="add-paper__other">
          <label className="add-paper__other-label" htmlFor={otherInputId}>{other.label || 'Name of the other value'} *</label>
          <input
            id={otherInputId}
            className={`toolbar__search ${otherInvalid ? 'is-invalid' : ''}`}
            placeholder={other.placeholder}
            value={other.value}
            onChange={(e) => other.onChange(e.target.value)}
            required
            aria-required="true"
            aria-invalid={otherInvalid || undefined}
            autoFocus={other.autoFocus ?? true}
          />
          {otherInvalid && <p className="add-paper__field-error">Enter a name, or pick one of the listed options instead.</p>}
        </div>
      )}
    </div>
  );
}
