import { useEffect, useMemo, useRef, useState } from 'react';
import { lookUpReference, parseReferences } from '@/lib/paperLookup';
import { looksLikeBibtex } from '@/lib/referenceExtract';
import { checkPapers, paperFromReference, papersFromJson, referenceTargets } from '@/lib/reviewPapers';
import { loadWorkspace, saveWorkspace, setWorkspaceActive } from '@/lib/workspace';
import { getDataSource } from '@/lib/data';
import { restartSite } from '@/lib/review';

const MODES = [
  { key: 'bibtex', label: 'BibTeX', placeholder: '@inproceedings{key,\n  title = {…},\n  author = {…},\n  year = {2024},\n  doi = {…}\n}' },
  { key: 'doi', label: 'DOIs', placeholder: 'One DOI per line, e.g. 10.1007/978-3-031-70396-6_1' },
  { key: 'citation', label: 'Citations', placeholder: 'One citation per line, in APA, MLA, IEEE or Springer LNCS style' },
  { key: 'json', label: 'JSON', placeholder: 'A list of papers coded against the schema, e.g. saved from Ariadne Lit' },
];

const plural = (n, one, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;
const sameSchema = (a, b) => JSON.stringify(a) === JSON.stringify(b);

/**
 * Loads papers into the visitor's own review, stored in this browser:
 * uncoded papers from BibTeX, DOIs or citations (completed from Crossref),
 * or coded papers from JSON. Every paper is checked against the review's
 * schema; problems are listed per paper, uncoded attributes only counted.
 */
export default function LoadPapersModal({ schema, onClose, onSaved }) {
  const [mode, setMode] = useState('bibtex');
  const [text, setText] = useState('');
  const [status, setStatus] = useState(null);
  const [error, setError] = useState(null);
  const [results, setResults] = useState(null);
  const [existing, setExisting] = useState(undefined);
  const [replace, setReplace] = useState(false);
  const [includeProblems, setIncludeProblems] = useState(false);
  const [name, setName] = useState(schema.title || 'My review');
  const [saved, setSaved] = useState(null);
  const fileRef = useRef(null);

  useEffect(() => {
    loadWorkspace().then(setExisting);
  }, []);

  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  // Papers can be added to the stored review only when it uses this schema.
  const canAdd = Boolean(existing && sameSchema(existing.schema, schema));
  const adding = canAdd && !replace;
  const kept = adding ? existing.papers : [];

  useEffect(() => {
    if (existing?.name) setName(existing.name);
  }, [existing]);

  const read = async (input, inputMode) => {
    setError(null);
    setResults(null);
    setSaved(null);
    if (!input.trim()) {
      setError('Paste papers or drop a file first.');
      return;
    }
    let papers;
    if (inputMode === 'json') {
      papers = papersFromJson(input);
      if (papers === null) { setError('This is not valid JSON.'); return; }
      if (!papers.length) { setError('No papers found: the JSON should hold papers with a "metadata" block.'); return; }
    } else {
      const references = parseReferences(input, inputMode);
      if (!references.length) {
        setError(inputMode === 'doi' ? 'No DOI found. Paste one DOI per line.' : 'No papers found in the text.');
        return;
      }
      const targets = referenceTargets(schema);
      papers = [];
      for (const reference of references) {
        setStatus(`Looking up papers in Crossref (${papers.length + 1} of ${references.length})…`);
        const { extracted } = await lookUpReference(reference);
        papers.push(paperFromReference(extracted, targets));
      }
      setStatus(null);
    }
    setResults(checkPapers(papers, schema, kept));
  };

  const readFile = async (file) => {
    if (!file) return;
    const content = await file.text();
    const fileMode = /\.json$/i.test(file.name) ? 'json'
      : /\.(bib|bibtex)$/i.test(file.name) || looksLikeBibtex(content) ? 'bibtex' : 'citation';
    setMode(fileMode);
    setText(content);
    read(content, fileMode);
  };

  // Rechecks duplicates when switching between adding and replacing.
  useEffect(() => {
    if (results) setResults(checkPapers(results.map((r) => r.paper), schema, kept));
  }, [adding]); // eslint-disable-line react-hooks/exhaustive-deps

  const summary = useMemo(() => {
    if (!results) return null;
    const fresh = results.filter((r) => !r.duplicate);
    return {
      total: results.length,
      duplicates: results.length - fresh.length,
      problems: fresh.filter((r) => r.errors.length),
      coded: fresh.filter((r) => !r.errors.length && !r.uncoded.length).length,
      uncoded: fresh.filter((r) => !r.errors.length && r.uncoded.length).length,
      toSave: fresh.filter((r) => includeProblems || !r.errors.length).map((r) => r.paper),
    };
  }, [results, includeProblems]);

  // Shows the saved review: switches it on (or, when it is already shown,
  // reloads it with the new papers).
  const showReview = async () => {
    setError(null);
    try {
      if (!existing?.active) await setWorkspaceActive(true);
      restartSite();
    } catch (e) {
      setError(`Could not show your review: ${e.message}`);
    }
  };
  const shown = getDataSource().kind === 'workspace';

  const save = async () => {
    setError(null);
    try {
      const papers = [...kept, ...summary.toSave];
      const record = await saveWorkspace({ name: name.trim() || 'My review', schema, papers, active: adding ? existing.active : false });
      setExisting(record);
      setSaved({ added: summary.toSave.length, total: papers.length });
      setResults(null);
      setText('');
      onSaved?.(record);
    } catch (e) {
      setError(`Could not save your review: ${e.message}`);
    }
  };

  return (
    <>
      <div className="modal__backdrop" onClick={onClose} />
      <div className="modal modal--wide" role="dialog" aria-modal="true" aria-labelledby="load-papers-title">
        <div className="modal__header">
          <h2 id="load-papers-title">Load Papers into Your Review</h2>
          <button className="paper-panel__close" onClick={onClose} aria-label="Close">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          </button>
        </div>
        <div className="modal__body">
          <p className="add-paper__hint">
            Papers you have not coded yet can come from BibTeX, DOIs or citations: title, authors, year and DOI are
            filled in from Crossref, and you code them later. Coded papers come from JSON. Every paper is checked against
            the schema of your review. Your review is stored in this browser only.
          </p>

          {existing === undefined ? null : existing ? (
            <div className="load-papers__existing">
              <p className="add-paper__hint">
                Your stored review <strong>{existing.name}</strong> has {plural(existing.papers.length, 'paper')}
                {canAdd ? '.' : ', coded against a different schema.'}
              </p>
              {canAdd ? (
                <div className="add-paper__toggles">
                  <label className="graph-controls__toggle">
                    <input type="radio" name="load-mode" checked={!replace} onChange={() => setReplace(false)} />
                    <span>Add to it</span>
                  </label>
                  <label className="graph-controls__toggle">
                    <input type="radio" name="load-mode" checked={replace} onChange={() => setReplace(true)} />
                    <span>Replace it</span>
                  </label>
                </div>
              ) : (
                <p className="add-paper__warning">Saving replaces it with a new review using this schema.</p>
              )}
            </div>
          ) : null}

          <div className="add-paper__tabs" role="tablist">
            {MODES.map((m) => (
              <button key={m.key} type="button" role="tab" aria-selected={mode === m.key}
                className={`btn btn--sm ${mode === m.key ? 'btn--primary' : 'btn--secondary'}`}
                onClick={() => { setMode(m.key); setError(null); }}>
                {m.label}
              </button>
            ))}
          </div>
          <textarea className="add-paper__textarea" rows={7} value={text} placeholder={MODES.find((m) => m.key === mode).placeholder}
            onChange={(e) => setText(e.target.value)} aria-label={`Papers as ${MODES.find((m) => m.key === mode).label}`} />
          <div className="load-papers__input-actions">
            <button type="button" className="btn btn--secondary btn--sm" onClick={() => fileRef.current?.click()}>Choose a File…</button>
            <span className="add-paper__hint">.bib, .txt or .json</span>
            <input ref={fileRef} type="file" accept=".bib,.bibtex,.txt,.json,application/json,text/plain" hidden
              onChange={(e) => { readFile(e.target.files?.[0]); e.target.value = ''; }} />
            <button type="button" className="btn btn--primary btn--sm load-papers__read" onClick={() => read(text, mode)} disabled={Boolean(status)}>
              Read Papers
            </button>
          </div>

          {status && <p className="add-paper__hint" role="status">{status}</p>}
          {error && <p className="add-paper__error" role="alert">{error}</p>}
          {saved && (
            <p className="add-paper__note add-paper__note--success" role="status">
              Saved {plural(saved.added, 'paper')}. Your review now has {plural(saved.total, 'paper')}.
            </p>
          )}

          {summary && (
            <section className="load-papers__result" aria-live="polite">
              <h3 className="add-paper__section">{plural(summary.total, 'paper')} read</h3>
              <ul className="load-papers__counts">
                <li><strong>{summary.coded}</strong> fully coded</li>
                <li><strong>{summary.uncoded}</strong> not fully coded yet</li>
                <li><strong>{summary.problems.length}</strong> with problems</li>
                {summary.duplicates > 0 && <li><strong>{summary.duplicates}</strong> already in your review or listed twice (skipped)</li>}
              </ul>

              {summary.problems.length > 0 && (
                <>
                  <details className="load-papers__problems" open={summary.problems.length <= 5}>
                    <summary>Problems, by paper</summary>
                    <ol>
                      {summary.problems.map((r, i) => (
                        <li key={i}>
                          <strong>{r.paper.metadata?.title || `Paper without a title (${r.paper.metadata?.doi_or_url || 'no DOI'})`}</strong>
                          <ul>{r.errors.map((e) => <li key={e}>{e}</li>)}</ul>
                        </li>
                      ))}
                    </ol>
                  </details>
                  <label className="graph-controls__toggle">
                    <input type="checkbox" checked={includeProblems} onChange={(e) => setIncludeProblems(e.target.checked)} />
                    <span>Also save the papers with problems, to fix them later</span>
                  </label>
                </>
              )}

              <div className="add-paper__field load-papers__name">
                <label className="filters-panel__label" htmlFor="review-name">Name of your review</label>
                <input id="review-name" className="toolbar__search" value={name} onChange={(e) => setName(e.target.value)} />
              </div>
            </section>
          )}

          <div className="modal__actions">
            <button type="button" className="btn btn--ghost" onClick={onClose}>{saved ? 'Done' : 'Cancel'}</button>
            {saved && !summary && (
              <button type="button" className="btn btn--primary" onClick={showReview}>
                {existing?.active && shown ? 'Reload to Show Them' : 'Show Your Review'}
              </button>
            )}
            {summary && (
              <button type="button" className="btn btn--primary" onClick={save} disabled={summary.toSave.length === 0}>
                {adding ? `Add ${plural(summary.toSave.length, 'Paper')} to Your Review` : `Save ${plural(summary.toSave.length, 'Paper')} as Your Review`}
              </button>
            )}
          </div>
        </div>
      </div>
    </>
  );
}
