import { useEffect, useMemo, useState } from 'react';
import {
  BUILDER_KINDS,
  FIXED_ATTRIBUTES,
  buildSchema,
  emptyDraft,
  loadDraft,
  newAttribute,
  otherKeyOf,
  parseValues,
  saveDraft,
  schemaFileName,
  toKey,
  validateDraft,
} from '@/lib/schemaBuilder';

const CHOICE = new Set(['single', 'multi']);

export default function BuildSchemaModal({ meta, onClose, onDownload, onUse }) {
  const [draft, setDraft] = useState(loadDraft);
  const [showErrors, setShowErrors] = useState(false);

  useEffect(() => saveDraft(draft), [draft]);

  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  const problems = useMemo(() => validateDraft(draft), [draft]);
  const valid = Object.keys(problems).length === 0;
  const schema = useMemo(() => (valid ? buildSchema(draft, meta) : null), [valid, draft, meta]);

  const setField = (key, value) => setDraft((d) => ({ ...d, [key]: value }));
  const updateAttr = (id, patch) => setDraft((d) => ({ ...d, attributes: d.attributes.map((a) => (a.id === id ? { ...a, ...patch } : a)) }));
  const removeAttr = (id) => setDraft((d) => ({ ...d, attributes: d.attributes.filter((a) => a.id !== id) }));
  const moveAttr = (id, step) => setDraft((d) => {
    const list = [...d.attributes];
    const i = list.findIndex((a) => a.id === id);
    const j = i + step;
    if (j < 0 || j >= list.length) return d;
    [list[i], list[j]] = [list[j], list[i]];
    return { ...d, attributes: list };
  });
  const addAttr = () => setDraft((d) => ({ ...d, attributes: [...d.attributes, newAttribute()] }));

  const finish = (action) => {
    if (!valid) {
      setShowErrors(true);
      return;
    }
    action(schema, schemaFileName(draft));
  };

  const startOver = () => {
    setDraft(emptyDraft());
    setShowErrors(false);
  };

  const errorFor = (key) => (showErrors ? problems[key] : null);
  const problemCount = Object.keys(problems).length;

  return (
    <>
      <div className="modal__backdrop" onClick={onClose} />
      <div className="modal modal--wide" role="dialog" aria-modal="true" aria-labelledby="build-schema-title">
        <div className="modal__header">
          <h2 id="build-schema-title">Build Schema</h2>
          <button className="paper-panel__close" onClick={onClose} aria-label="Close">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          </button>
        </div>
        <div className="modal__body">
          <p className="add-paper__hint">
            Describe the attributes you code your papers by. The result is a JSON Schema that Ariadne Lit can read,
            with a suggested use in each view. Your draft is kept in this browser until you start over.
          </p>

          <div className="add-paper__grid">
            <div className="add-paper__field">
              <label className="filters-panel__label" htmlFor="schema-title">Schema title *</label>
              <input id="schema-title" className={`toolbar__search ${errorFor('_title') ? 'is-invalid' : ''}`}
                placeholder="e.g. Requirements Engineering Studies" value={draft.title}
                onChange={(e) => setField('title', e.target.value)} />
              {errorFor('_title') && <p className="add-paper__field-error">{errorFor('_title')}</p>}
            </div>
            <div className="add-paper__field">
              <label className="filters-panel__label" htmlFor="schema-description">Description</label>
              <input id="schema-description" className="toolbar__search" placeholder="What the schema classifies"
                value={draft.description} onChange={(e) => setField('description', e.target.value)} />
            </div>
          </div>

          <h3 className="add-paper__section">Included in Every Schema</h3>
          <p className="add-paper__hint">The views need these attributes, so they are always added.</p>
          <ul className="build-schema__fixed">
            {FIXED_ATTRIBUTES.map((f) => (
              <li key={f.path}>
                <strong>{f.label}</strong>
                <span className="build-schema__meta">{f.kind} · {f.note}</span>
              </li>
            ))}
          </ul>

          <h3 className="add-paper__section">Your Attributes</h3>
          {errorFor('_form') && <p className="add-paper__error" role="alert">{errorFor('_form')}</p>}
          <ol className="build-schema__list">
            {draft.attributes.map((a, i) => {
              const kind = BUILDER_KINDS.find((k) => k.key === a.kind);
              const error = errorFor(a.id);
              const key = toKey(a.name);
              const values = parseValues(a.values);
              return (
                <li key={a.id} className={`build-schema__attr ${error ? 'is-invalid' : ''}`}>
                  <div className="build-schema__attr-head">
                    <span className="build-schema__index">{i + 1}</span>
                    <div className="build-schema__attr-tools">
                      <button type="button" className="btn btn--ghost btn--sm" onClick={() => moveAttr(a.id, -1)} disabled={i === 0} aria-label={`Move attribute ${i + 1} up`}>↑</button>
                      <button type="button" className="btn btn--ghost btn--sm" onClick={() => moveAttr(a.id, 1)} disabled={i === draft.attributes.length - 1} aria-label={`Move attribute ${i + 1} down`}>↓</button>
                      <button type="button" className="btn btn--ghost btn--sm" onClick={() => removeAttr(a.id)}>Remove</button>
                    </div>
                  </div>
                  <div className="add-paper__grid build-schema__grid">
                    <div className="add-paper__field">
                      <label className="filters-panel__label" htmlFor={`${a.id}-name`}>Name *</label>
                      <input id={`${a.id}-name`} className="toolbar__search" placeholder="e.g. Research method" value={a.name}
                        onChange={(e) => updateAttr(a.id, { name: e.target.value })} />
                      {key && <span className="build-schema__meta">Stored as <code>{key}</code></span>}
                    </div>
                    <div className="add-paper__field">
                      <label className="filters-panel__label" htmlFor={`${a.id}-kind`}>Type</label>
                      <select id={`${a.id}-kind`} className="ax-select build-schema__select" value={a.kind}
                        onChange={(e) => updateAttr(a.id, { kind: e.target.value })}>
                        {BUILDER_KINDS.map((k) => <option key={k.key} value={k.key}>{k.label}</option>)}
                      </select>
                      <span className="build-schema__meta">{kind?.hint}</span>
                    </div>
                  </div>
                  {CHOICE.has(a.kind) && (
                    <div className="add-paper__field">
                      <label className="filters-panel__label" htmlFor={`${a.id}-values`}>Values * (comma-separated)</label>
                      <input id={`${a.id}-values`} className="toolbar__search build-schema__wide" placeholder="e.g. case study, experiment, survey"
                        value={a.values} onChange={(e) => updateAttr(a.id, { values: e.target.value })} />
                      {values.length > 0 && (
                        <span className="build-schema__meta">
                          {values.length} {values.length === 1 ? 'value' : 'values'}{a.allowOther ? ' + Other' : ''}
                        </span>
                      )}
                      <label className="graph-controls__toggle build-schema__other">
                        <input type="checkbox" checked={Boolean(a.allowOther)} onChange={(e) => updateAttr(a.id, { allowOther: e.target.checked })} />
                        <span>Allow "Other" with a required name</span>
                      </label>
                      {a.allowOther && (
                        <span className="build-schema__meta">
                          Adds the value <code>other</code>. Choosing it requires a name, stored in{' '}
                          <code>{otherKeyOf(key || 'attribute')}</code>.
                        </span>
                      )}
                    </div>
                  )}
                  <div className="add-paper__field">
                    <label className="filters-panel__label" htmlFor={`${a.id}-description`}>Description</label>
                    <input id={`${a.id}-description`} className="toolbar__search build-schema__wide" placeholder="How coders should decide the value"
                      value={a.description} onChange={(e) => updateAttr(a.id, { description: e.target.value })} />
                  </div>
                  {error && <p className="add-paper__field-error">{error}</p>}
                </li>
              );
            })}
          </ol>
          <button type="button" className="btn btn--secondary btn--sm" onClick={addAttr}>+ Add Attribute</button>

          {schema && (
            <details className="build-schema__preview">
              <summary>Preview JSON</summary>
              <pre><code>{JSON.stringify(schema, null, 2)}</code></pre>
            </details>
          )}

          {showErrors && !valid && (
            <p className="add-paper__error" role="alert">
              Fix the {problemCount === 1 ? 'marked field' : `${problemCount} marked fields`} first.
            </p>
          )}

          <div className="modal__actions">
            <button type="button" className="btn btn--ghost" onClick={startOver}>Start Over</button>
            <div className="add-paper__nav">
              <button type="button" className="btn btn--secondary" onClick={() => finish(onDownload)}>Download Schema</button>
              <button type="button" className="btn btn--primary" onClick={() => finish(onUse)}
                title="Opens the schema in the table below, where you can change how each view uses it">
                Review Views →
              </button>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
