import { useEffect, useMemo, useRef, useState } from 'react';
import { addUserPapers, updateUserPaper } from '@/lib/data';
import { proposePapers } from '@/lib/proposal';
import { doiKey, lookUpReference, parseReferences } from '@/lib/paperLookup';
import { looksLikeBibtex } from '@/lib/referenceExtract';
import ChipSelect from '@/components/ChipSelect';
import { NAMED, NAME_SEPARATOR, isNamed, namedChips, rankNames, splitList, splitNames, toggleMulti, toggleSingle } from '@/lib/formLists';

const TRACKS = ['Engineering', 'Foundations', 'Management'];
const OTHER_TRACK = 'Other';

function trackOptions(papers, current) {
  const byKey = new Map(TRACKS.map((t) => [t.toLowerCase(), { name: t, count: Infinity }]));
  const count = (track, n) => {
    const name = (track || '').trim();
    if (!name || name.toLowerCase() === OTHER_TRACK.toLowerCase()) return;
    const entry = byKey.get(name.toLowerCase()) || { name, count: 0 };
    entry.count += n;
    byKey.set(name.toLowerCase(), entry);
  };
  (papers || []).forEach((p) => count(p.metadata?.track, 1));
  count(current, 0);
  const learned = [...byKey.values()]
    .filter((e) => e.count !== Infinity)
    .sort((a, b) => b.count - a.count || a.name.localeCompare(b.name))
    .map((e) => e.name);
  return [...TRACKS, ...learned, OTHER_TRACK].map((t) => ({ id: t, label: t }));
}
const THEORY_TYPES = ['formal_theory', 'social_science_theory'];
const EMPHASES = ['theory', 'artifact'];
const CODE_GETTERS = {
  researchMethod: (a) => a.research_method?.methods,
  evaluationMethod: (a) => a.evaluation_method,
  dataType: (a) => a.data_collection?.data_type,
  threatsToValidity: (a) => a.threats_to_validity,
};

/** Coded attributes that offer an "Other" chip; picking it requires the
 * name of that other value, stored in `otherKey` of the form. */
const OTHER_CODES = {
  researchMethod: { otherKey: 'researchMethodOther', label: 'Research Method', name: 'Name of the other research method', getName: (a) => a.research_method?.other },
  evaluationMethod: { otherKey: 'evaluationMethodOther', label: 'Evaluation Method', name: 'Name of the other evaluation method', getName: (a) => a.evaluation_method_other },
  threatsToValidity: { otherKey: 'threatsToValidityOther', label: 'Reflection on Threats to Validity', name: 'Name of the other threat to validity', getName: (a) => a.threats_to_validity_other },
};
const OTHER_CODE = 'other';


function codeOptions(papers, getter, selected = []) {
  const counts = new Map();
  (papers || []).forEach((p) => (p.contribution?.artifacts || []).forEach((a) => (getter(a) || []).forEach((v) => counts.set(v, (counts.get(v) || 0) + 1))));
  selected.forEach((v) => { if (!counts.has(v)) counts.set(v, 0); });
  return [...counts.entries()].sort((x, y) => y[1] - x[1] || x[0].localeCompare(y[0])).map(([v]) => v);
}

function namedOptions(papers, getName, selected = []) {
  const typed = (papers || []).flatMap((p) => (p.contribution?.artifacts || []).flatMap((a) => splitNames(getName(a))));
  return namedChips(rankNames(typed, selected.filter(isNamed).map((id) => id.slice(NAMED.length))));
}

const isOtherCode = (v) => /^other$/i.test(v);

function otherNames(form, key) {
  const typed = form[key].some(isOtherCode) ? form[OTHER_CODES[key].otherKey].trim() : '';
  const names = [...form[key].filter(isNamed).map((id) => id.slice(NAMED.length)), ...(typed ? [typed] : [])];
  const seen = new Set();
  return names.filter((n) => !seen.has(n.toLowerCase()) && seen.add(n.toLowerCase()));
}

function codesOf(form, key) {
  const codes = form[key].filter((v) => !isNamed(v) && !isOtherCode(v));
  return otherNames(form, key).length ? [...codes, OTHER_CODE] : codes;
}

const otherText = (form, key) => otherNames(form, key).join(NAME_SEPARATOR);

const chipsFrom = (codes, names) => [...(codes || []).filter((v) => !isOtherCode(v)), ...splitNames(names).map((n) => `${NAMED}${n}`)];

const EMPTY_FORM = {
  title: '',
  authors: '',
  year: '',
  track: '',
  trackIsOther: false,
  doiOrUrl: '',
  conferenceAbbreviationIsOther: false,
  conferenceName: '',
  conferenceAbbreviation: '',
  keywords: '',
  typeOfInquiry: [],
  typeOfArtifact: [],
  researchMethod: [],
  evaluationMethod: [],
  dataType: [],
  threatsToValidity: [],
  researchMethodOther: '',
  evaluationMethodOther: '',
  threatsToValidityOther: '',
  implementationExistence: false,
  implementationAvailability: false,
  typeOfTheory: [],
  emphasis: [],
  formalConcepts: false,
  algorithms: false,
  hypothesis: false,
  independentVariables: '',
  dependentVariables: '',
};




function buildRecord(form, conferences) {
  const conference = resolveConference(form, conferences);
  return {
    _userAdded: true,
    _userKey: `user-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    metadata: {
      title: form.title.trim(),
      authors: splitList(form.authors),
      doi_or_url: form.doiOrUrl.trim(),
      year: Number(form.year) || undefined,
      conference_name: form.conferenceName.trim(),
      conference_abbreviation: conference.abbreviation,
      track: form.track.trim(),
    },
    contribution: {
      keywords: splitList(form.keywords),
      focus_intent: {
        type_of_inquiry: form.typeOfInquiry,
      },
      research_components: {
        type_of_theory: form.typeOfTheory,
        emphasis: form.emphasis,
        formal_concepts: form.formalConcepts,
        algorithms: form.algorithms,
        hypothesis: form.hypothesis,
        ...(form.hypothesis && form.independentVariables.trim() ? { independent_variables: form.independentVariables.trim() } : {}),
        ...(form.hypothesis && form.dependentVariables.trim() ? { dependent_variables: form.dependentVariables.trim() } : {}),
      },
      artifacts: [
        {
          type_of_artifact: form.typeOfArtifact,
          research_method: {
            methods: codesOf(form, 'researchMethod'),
            ...(otherText(form, 'researchMethod') ? { other: otherText(form, 'researchMethod') } : {}),
          },
          evaluation_method: codesOf(form, 'evaluationMethod'),
          ...(otherText(form, 'evaluationMethod') ? { evaluation_method_other: otherText(form, 'evaluationMethod') } : {}),
          data_collection: { data_type: form.dataType },
          threats_to_validity: codesOf(form, 'threatsToValidity'),
          ...(otherText(form, 'threatsToValidity') ? { threats_to_validity_other: otherText(form, 'threatsToValidity') } : {}),
          implementation: {
            existence: form.implementationExistence,
            availability: form.implementationAvailability,
          },
        },
      ],
    },
  };
}


const conferenceKey = (s) => (s || '').toLowerCase().normalize('NFD').replace(/[^a-z0-9]/g, '');

function conferenceOptions(papers) {
  const byKey = new Map();
  (papers || []).forEach((p) => {
    const abbreviation = (p.metadata?.conference_abbreviation || '').trim();
    if (!abbreviation) return;
    const id = conferenceKey(abbreviation);
    const entry = byKey.get(id) || { id, label: abbreviation, name: '', count: 0 };
    entry.count += 1;
    if (!entry.name && p.metadata?.conference_name) entry.name = p.metadata.conference_name.trim();
    byKey.set(id, entry);
  });
  return [...byKey.values()].sort((a, b) => b.count - a.count || a.label.localeCompare(b.label));
}

function resolveConference(form, conferences) {
  const abbreviation = form.conferenceAbbreviation.trim();
  const option = !form.conferenceAbbreviationIsOther && abbreviation
    ? conferences.find((c) => c.id === conferenceKey(abbreviation)) || null
    : null;
  if (option) return { abbreviation: option.label, option, isOther: false };
  return { abbreviation, option: null, isOther: form.conferenceAbbreviationIsOther || Boolean(abbreviation) };
}

function missingFieldsOf(form, conferences) {
  const conference = resolveConference(form, conferences);
  return [
    !form.title.trim() && 'Title',
    !form.doiOrUrl.trim() && 'DOI / URL',
    conference.isOther && !conference.abbreviation && 'Conference abbreviation (for "Other")',
    form.trackIsOther && !form.track.trim() && 'Track name (for "Other")',
    ...Object.entries(OTHER_CODES).map(([key, o]) => (
      form[key].some((v) => /^other$/i.test(v)) && !form[o.otherKey].trim() && `${o.label} name (for "Other")`
    )),
    form.typeOfInquiry.length === 0 && 'Type of Inquiry',
    form.typeOfArtifact.length === 0 && 'Type of Artifact',
  ].filter(Boolean);
}

function formFrom(x) {
  return {
    ...EMPTY_FORM,
    title: x.title || '',
    authors: (x.authors || []).join(', '),
    year: x.year ? String(x.year) : '',
    doiOrUrl: x.doi_or_url || '',
    conferenceName: x.conference_name || '',
    conferenceAbbreviation: x.conference_abbreviation || '',
    keywords: (x.keywords || []).join(', '),
  };
}

function formFromRecord(record) {
  const m = record.metadata || {};
  const c = record.contribution || {};
  const artifact = c.artifacts?.[0] || {};
  const track = m.track || '';
  const trackIsOther = false;
  return {
    ...formFrom({ ...m, keywords: c.keywords }),
    track,
    trackIsOther,
    typeOfInquiry: c.focus_intent?.type_of_inquiry || [],
    typeOfArtifact: artifact.type_of_artifact || [],
    researchMethod: chipsFrom(artifact.research_method?.methods, artifact.research_method?.other),
    evaluationMethod: chipsFrom(artifact.evaluation_method, artifact.evaluation_method_other),
    dataType: artifact.data_collection?.data_type || [],
    threatsToValidity: chipsFrom(artifact.threats_to_validity, artifact.threats_to_validity_other),
    implementationExistence: Boolean(artifact.implementation?.existence),
    implementationAvailability: Boolean(artifact.implementation?.availability),
    typeOfTheory: c.research_components?.type_of_theory || [],
    emphasis: c.research_components?.emphasis || [],
    formalConcepts: Boolean(c.research_components?.formal_concepts),
    algorithms: Boolean(c.research_components?.algorithms),
    hypothesis: Boolean(c.research_components?.hypothesis),
    independentVariables: c.research_components?.independent_variables || '',
    dependentVariables: c.research_components?.dependent_variables || '',
  };
}

async function enrichAll(items, onProgress) {
  const results = [];
  for (const item of items) {
    results.push(await lookUpReference(item));
    onProgress(results.length, items.length);
  }
  return results.map(({ extracted, notice }, i) => ({
    key: `${i}-${extracted.label || extracted.title || ''}`,
    label: extracted.title || extracted.label || `Paper ${i + 1}`,
    form: formFrom(extracted),
    notice,
    added: false,
  }));
}

function recordsFromJson(text) {
  let data;
  try {
    data = JSON.parse(text);
  } catch {
    return null;
  }
  if (!data || typeof data !== 'object') return null;
  const list = Array.isArray(data) ? data : [data];
  return list.filter((r) => r && typeof r === 'object' && r.metadata && r.contribution);
}

function draftsFromRecords(records, papers) {
  const known = new Set((papers || []).map((p) => doiKey(p.metadata?.doi_or_url)).filter(Boolean));
  return records.map((record, i) => {
    const doi = doiKey(record.metadata.doi_or_url);
    return {
      key: `json-${i}-${record.metadata.title || ''}`,
      label: record.metadata.title || `Paper ${i + 1}`,
      form: formFromRecord(record),
      notice: doi && known.has(doi) ? 'A paper with this DOI is already in the collection.' : undefined,
      added: false,
    };
  });
}

const draftState = (d, conferences) => (d.added ? 'added' : missingFieldsOf(d.form, conferences).length ? 'incomplete' : 'ready');
const STATE_TEXT = { added: 'added', incomplete: 'needs coding', ready: 'ready to add' };


export default function AddPaperModal({ config, papers, editing = null, onClose, onAdded, onSaved }) {
  const conferences = useMemo(() => conferenceOptions(papers), [papers]);
  const [step, setStep] = useState(editing ? 'review' : 'input');
  const [inputMode, setInputMode] = useState('bibtex');
  const [inputValue, setInputValue] = useState('');
  const [status, setStatus] = useState(null);
  const [dragging, setDragging] = useState(false);
  const [error, setError] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [drafts, setDrafts] = useState(() => (
    editing ? [{ key: 'edit', label: editing.metadata?.title || 'Paper', form: formFromRecord(editing), added: false }] : []
  ));
  const [current, setCurrent] = useState(0);
  const [addedPapers, setAddedPapers] = useState([]);
  const [proposeKeys, setProposeKeys] = useState(() => new Set());
  // Field-level errors appear only after a first submit attempt.
  const [attempted, setAttempted] = useState(false);
  // Bumped on every failed submit, so the error is brought into view again
  // even when its text has not changed.
  const [errorNonce, setErrorNonce] = useState(0);
  const errorRef = useRef(null);
  const fileRef = useRef(null);
  const bodyRef = useRef(null);

  useEffect(() => {
    if (!error || !errorRef.current) return;
    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
    errorRef.current.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth', block: 'center' });
    errorRef.current.focus({ preventScroll: true });
  }, [error, errorNonce]);

  const showError = (message) => {
    setError(message);
    setErrorNonce((n) => n + 1);
  };

  const pending = drafts.filter((d) => !d.added);
  const isBatch = drafts.length > 1;
  const draft = drafts[current];
  const form = draft?.form || EMPTY_FORM;

  const setForm = (update) => setDrafts((list) => list.map((d, i) => (i === current ? { ...d, form: update(d.form) } : d)));
  const setField = (key, value) => setForm((f) => ({ ...f, [key]: value }));
  const setMultiChip = (key, value) => setForm((f) => ({ ...f, [key]: toggleMulti(f[key], value) }));
  const setSingleChip = (key, value) => setForm((f) => ({ ...f, [key]: toggleSingle(f[key], value) }));

  const goTo = (i) => {
    setCurrent(i);
    setError(null);
    bodyRef.current?.scrollTo({ top: 0 });
  };

  const startReview = (list) => {
    setDrafts(list);
    setCurrent(0);
    setAttempted(false);
    setStep('review');
    const first = list[0];
    if (list.length === 1 && first.notice) showError(first.notice);
    else setError(null);
  };

  const extract = async (items, coded = []) => {
    if (items.length === 0 && coded.length === 0) {
      showError(
        inputMode === 'doi'
          ? 'No DOI found. Paste one or more DOIs, one per line.'
          : 'No entries found. Paste BibTeX entries or citations, or drop a .bib, .txt or .json file.'
      );
      return;
    }
    setError(null);
    if (items.length === 0) {
      startReview(coded);
      return;
    }
    setStatus(`Looking up ${items.length === 1 ? 'the paper' : `${items.length} papers`} in CrossRef…`);
    try {
      const list = await enrichAll(items, (done, total) => {
        if (total > 1) setStatus(`Looking up papers in CrossRef (${done} of ${total})…`);
      });
      startReview([...coded, ...list]);
    } finally {
      setStatus(null);
    }
  };

  const handleExtract = () => {
    if (!inputValue.trim()) {
      showError('Paste one or more DOIs, BibTeX entries, citations or saved papers (JSON) first.');
      return;
    }
    const records = recordsFromJson(inputValue);
    if (records) {
      if (records.length) extract([], draftsFromRecords(records, papers));
      else showError('No papers found in the pasted JSON. Each paper needs "metadata" and "contribution".');
      return;
    }
    extract(parseReferences(inputValue, inputMode));
  };

  const handleFiles = async (fileList) => {
    const files = [...(fileList || [])];
    if (files.length === 0) return;
    const items = [];
    const records = [];
    const unreadable = [];
    for (const file of files) {
      const text = await file.text();
      const found = recordsFromJson(text);
      if (found || /\.json$/i.test(file.name)) {
        if (found?.length) records.push(...found);
        else unreadable.push(file.name);
        continue;
      }
      const mode = /\.(bib|bibtex)$/i.test(file.name) || looksLikeBibtex(text) ? 'bibtex' : 'citation';
      items.push(...parseReferences(text, mode));
    }
    if (unreadable.length && items.length === 0 && records.length === 0) {
      showError(`No papers found in ${unreadable.join(', ')}. A JSON file must hold papers saved by Ariadne Lit, each with "metadata" and "contribution".`);
      return;
    }
    await extract(items, draftsFromRecords(records, papers));
    if (unreadable.length) showError(`Skipped ${unreadable.join(', ')}: no papers saved by Ariadne Lit found.`);
  };

  const codeWithOther = (key) => {
    const o = OTHER_CODES[key];
    return (
      <ChipSelect
        label={o.label}
        options={[
          ...codeOptions(papers, CODE_GETTERS[key], form[key].filter((v) => !isNamed(v))).filter((v) => !isOtherCode(v)),
          ...namedOptions(papers, o.getName, form[key]),
          OTHER_CODE,
        ]}
        selected={form[key]}
        onToggle={(id) => setMultiChip(key, id)}
        other={{
          label: o.name,
          value: form[o.otherKey],
          onChange: (v) => setField(o.otherKey, v),
          showError: attempted,
        }}
      />
    );
  };

  const missingFields = missingFieldsOf(form, conferences);
  const readyCount = drafts.filter((d) => draftState(d, conferences) === 'ready').length;
  const onLastDraft = current === drafts.length - 1;
  const conference = resolveConference(form, conferences);
  const tracks = trackOptions(papers, form.trackIsOther ? '' : form.track);

  const addDrafts = async (toAdd) => {
    setError(null);
    setSubmitting(true);
    try {
      const records = toAdd.map((d) => buildRecord(d.form, conferences));
      const papers = await addUserPapers(records);
      const addedKeys = new Set(toAdd.map((d) => d.key));
      setDrafts((list) => list.map((d) => (addedKeys.has(d.key) ? { ...d, added: true } : d)));
      setAddedPapers(papers);
      setProposeKeys(new Set(papers.map((p) => p._userKey)));
      onAdded(papers[papers.length - 1] || null);
      setStep('success');
    } catch (e) {
      showError(`Could not add the paper: ${e.message || 'unknown error'}`);
    } finally {
      setSubmitting(false);
    }
  };

  const saveEdit = async () => {
    setError(null);
    setSubmitting(true);
    try {
      const { _id: _ignored, ...kept } = editing;
      const record = { ...kept, ...buildRecord(draft.form, conferences), _userKey: editing._userKey, _editedAt: new Date().toISOString() };
      const paper = await updateUserPaper(record);
      onSaved?.(paper);
      onClose();
    } catch (e) {
      showError(`Could not save the paper: ${e.message || 'unknown error'}`);
    } finally {
      setSubmitting(false);
    }
  };

  const handleSubmit = () => {
    setAttempted(true);
    if (!isBatch) {
      if (missingFields.length) {
        showError(`Please fill in the required fields before submitting: ${missingFields.join(', ')}.`);
        return;
      }
      if (editing) saveEdit();
      else addDrafts([draft]);
      return;
    }
    const ready = drafts.filter((d) => draftState(d, conferences) === 'ready');
    if (ready.length === 0) {
      showError(
        `None of the papers is ready yet. Paper ${current + 1} still needs: ${missingFields.join(', ') || 'nothing (it was already added)'}.`
      );
      return;
    }
    addDrafts(ready);
  };

  const toPropose = addedPapers.filter((p) => proposeKeys.has(p._userKey));

  const toggleProposal = (key) => setProposeKeys((prev) => {
    const next = new Set(prev);
    if (next.has(key)) next.delete(key); else next.add(key);
    return next;
  });

  const handleProposeAll = () => {
    if (toPropose.length === 0) return;
    proposePapers(toPropose).then(() => onAdded(null));
  };

  const continueRemaining = () => {
    const rest = drafts.filter((d) => !d.added);
    setDrafts(rest);
    setCurrent(0);
    setAttempted(false);
    setError(null);
    setStep('review');
  };

  return (
    <>
      <div className="modal__backdrop" onClick={onClose} />
      <div className="modal" role="dialog" aria-labelledby="add-paper-title">
        <div className="modal__header">
          <h2 id="add-paper-title">{editing ? 'Edit Paper' : 'Add Papers'}</h2>
          <button className="paper-panel__close" onClick={onClose} aria-label="Close">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="modal__body" ref={bodyRef}>
          {step === 'input' && (
            <>
              <p className="add-paper__hint">
                Add one paper or many at once. Title, authors, year, DOI and conference are filled in from DOIs, BibTeX
                and citations, and looked up in CrossRef. You then code each paper before it is added.  Previously coded papers, 
                can be added by pasting the JSON data or dropping a .json file. 
                
                Added papers live only in your browser (nothing is uploaded automatically) and show up in the Papers list, filters and the
                Metagraph, marked as yours.
              </p>
              <div className="add-paper__tabs">
                {['bibtex', 'doi', 'citation'].map((mode) => (
                  <button
                    key={mode}
                    type="button"
                    className={`btn btn--sm ${inputMode === mode ? 'btn--primary' : 'btn--secondary'}`}
                    onClick={() => { setInputMode(mode); setError(null); }}
                  >
                    {mode === 'doi' ? 'DOI' : mode === 'bibtex' ? 'BibTeX' : 'Citation'}
                  </button>
                ))}
              </div>

              <textarea
                className="add-paper__textarea"
                rows={inputMode === 'doi' ? 4 : 7}
                placeholder={
                  inputMode === 'doi'
                    ? 'One DOI per line, e.g.\n10.1007/978-3-031-70396-6_13\nhttps://doi.org/...'
                    : inputMode === 'bibtex'
                      ? '@inproceedings{key, title={...}, author={...}, booktitle={...}, year={...}, doi={...}}\n@article{...}'
                      : 'Paste plain-text citations (APA, MLA, IEEE, Springer LNCS, ...)'
                }
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                disabled={Boolean(status)}
              />

              <div
                className={`add-paper__dropzone ${dragging ? 'add-paper__dropzone--active' : ''}`}
                onClick={() => !status && fileRef.current?.click()}
                onKeyDown={(e) => {
                  if (!status && (e.key === 'Enter' || e.key === ' ')) {
                    e.preventDefault();
                    fileRef.current?.click();
                  }
                }}
                onDragOver={(e) => {
                  e.preventDefault();
                  setDragging(true);
                }}
                onDragLeave={() => setDragging(false)}
                onDrop={(e) => {
                  e.preventDefault();
                  setDragging(false);
                  if (!status) handleFiles(e.dataTransfer.files);
                }}
                role="button"
                tabIndex={0}
                aria-busy={Boolean(status)}
              >
                {status ? (
                  <>
                    <div className="loading__spinner" />
                    <span>{status}</span>
                  </>
                ) : (
                  <>
                    <strong>Drop .bib, .txt or .json files here</strong>
                    <span>
                      or click to choose them. A .bib file can hold many BibTeX entries, a .txt file a numbered list of
                      citations, and a .json file papers already coded and saved with Ariadne Lit, which keep their codes.
                    </span>
                  </>
                )}
              </div>
              <input
                ref={fileRef}
                type="file"
                accept=".bib,.bibtex,.txt,.json,text/plain,application/x-bibtex,application/json"
                multiple
                hidden
                onChange={(e) => {
                  handleFiles(e.target.files);
                  e.target.value = '';
                }}
              />

              {error && <p ref={errorRef} className="add-paper__error" role="alert" tabIndex={-1}>{error}</p>}

              <div className="modal__actions">
                <button className="btn btn--ghost" onClick={() => startReview([{ key: 'manual', label: 'New paper', form: EMPTY_FORM, added: false }])} disabled={Boolean(status)}>
                  Skip — enter manually
                </button>
                <button className="btn btn--primary" onClick={handleExtract} disabled={Boolean(status)}>
                  {status ? 'Looking up…' : 'Extract'}
                </button>
              </div>
            </>
          )}

          {step === 'review' && draft && (
            <>
              {isBatch && (
                <>
                  <p className="add-paper__batch">
                    Paper {current + 1} of {drafts.length} · {readyCount} ready to add
                  </p>
                  <div className="add-paper__steps" role="tablist">
                    {drafts.map((d, i) => {
                      const state = draftState(d, conferences);
                      return (
                        <button
                          key={d.key}
                          type="button"
                          role="tab"
                          aria-selected={i === current}
                          className={`add-paper__step add-paper__step--${state}${i === current ? ' add-paper__step--current' : ''}`}
                          title={`${d.form.title || d.label}: ${STATE_TEXT[state]}`}
                          onClick={() => goTo(i)}
                        >
                          {i + 1}. {d.form.title || d.label}
                        </button>
                      );
                    })}
                  </div>
                </>
              )}
              <p className="add-paper__hint">
                {editing
                  ? 'Change the fields you want to correct and save. The paper stays in your browser only.'
                  : draft.added
                    ? 'This paper has been added already.'
                    : 'Verify the extracted fields, fill in whatever is missing, and code the paper below.'}
              </p>
              {editing?._proposedAt && (
                <p className="add-paper__warning">
                  You proposed this paper on {new Date(editing._proposedAt).toLocaleDateString()}. Your changes stay in your
                  browser until you propose it again.
                </p>
              )}
              {isBatch && draft.notice && <p className="add-paper__warning">{draft.notice}</p>}
              {error && <p ref={errorRef} className="add-paper__error" role="alert" tabIndex={-1}>{error}</p>}

              <fieldset className="add-paper__fieldset" disabled={draft.added}>
              <div className="add-paper__grid">
                <div className="add-paper__field">
                  <label className="filters-panel__label">Title *</label>
                  <input className="toolbar__search" value={form.title} onChange={(e) => setField('title', e.target.value)} />
                </div>
                <div className="add-paper__field">
                  <label className="filters-panel__label">Authors (comma-separated)</label>
                  <input className="toolbar__search" value={form.authors} onChange={(e) => setField('authors', e.target.value)} />
                </div>
                <div className="add-paper__field">
                  <label className="filters-panel__label">Year</label>
                  <input className="toolbar__search" type="number" value={form.year} onChange={(e) => setField('year', e.target.value)} />
                </div>
                <div className="add-paper__field">
                  <label className="filters-panel__label">DOI / URL *</label>
                  <input className="toolbar__search" value={form.doiOrUrl} onChange={(e) => setField('doiOrUrl', e.target.value)} />
                </div>
                <div className="add-paper__field">
                  <label className="filters-panel__label">Conference</label>
                  <input
                    className="toolbar__search"
                    placeholder="e.g. International Conference on Business Process Management"
                    value={form.conferenceName}
                    onChange={(e) => setField('conferenceName', e.target.value)}
                  />
                </div>
                <div className="add-paper__field">
                  <label className="filters-panel__label">Keywords (comma-separated)</label>
                  <input className="toolbar__search" value={form.keywords} onChange={(e) => setField('keywords', e.target.value)} />
                </div>
              </div>

              <ChipSelect
                label="Conference abbreviation"
                options={[...conferences, { id: 'Other', label: 'Other' }]}
                selected={conference.isOther ? ['Other'] : conference.option ? [conference.option.id] : []}
                onToggle={(id) => {
                  if (id === 'Other') {
                    setForm((f) => (conference.isOther ? f : { ...f, conferenceAbbreviationIsOther: true, conferenceAbbreviation: '' }));
                    return;
                  }
                  const picked = conferences.find((c) => c.id === id);
                  const same = conference.option?.id === id;
                  setForm((f) => ({
                    ...f,
                    conferenceAbbreviationIsOther: false,
                    conferenceAbbreviation: same ? '' : picked.label,
                    conferenceName: !same && !f.conferenceName.trim() ? picked.name : f.conferenceName,
                  }));
                }}
                other={{
                  label: 'Conference abbreviation',
                  placeholder: 'e.g. ICPM',
                  value: form.conferenceAbbreviation,
                  onChange: (v) => setForm((f) => ({ ...f, conferenceAbbreviationIsOther: true, conferenceAbbreviation: v })),
                  showError: attempted,
                }}
              />

              <ChipSelect
                label="Track"
                options={tracks}
                selected={form.trackIsOther ? [OTHER_TRACK] : form.track ? [tracks.find((t) => t.id.toLowerCase() === form.track.trim().toLowerCase())?.id || form.track] : []}
                onToggle={(id) => {
                  if (id === OTHER_TRACK) setForm((f) => ({ ...f, trackIsOther: true, track: '' }));
                  else setForm((f) => ({ ...f, trackIsOther: false, track: f.track === id ? '' : id }));
                }}
                other={{
                  label: 'Track name',
                  placeholder: 'e.g. Process Mining Forum',
                  value: form.track,
                  onChange: (v) => setField('track', v),
                  showError: attempted,
                }}
              />

              <p className="add-paper__hint">
                These can't be extracted from a citation — pick what applies. Type of Inquiry and Type of Artifact
                (single choice, required) drive how this paper is classified and clustered.
              </p>

              <ChipSelect
                label="Type of Inquiry * (pick one)"
                options={config.typesOfInquiry || []}
                selected={form.typeOfInquiry}
                onToggle={(id) => setSingleChip('typeOfInquiry', id)}
                colorOf={(id) => config.typesOfInquiry?.find((t) => t.id === id)?.color}
              />
              <ChipSelect
                label="Type of Artifact * (pick one)"
                options={config.typesOfArtifact || []}
                selected={form.typeOfArtifact}
                onToggle={(id) => setSingleChip('typeOfArtifact', id)}
                colorOf={(id) => config.typesOfArtifact?.find((t) => t.id === id)?.color}
              />

              <h3 className="add-paper__section">Research Components</h3>
              <ChipSelect
                label="Type of Theory"
                hint="Pick both for a combined formal and social science contribution."
                options={THEORY_TYPES}
                selected={form.typeOfTheory}
                onToggle={(id) => setMultiChip('typeOfTheory', id)}
              />
              <ChipSelect
                label="Emphasis"
                hint="Pick both for a dual emphasis on theory and artifact."
                options={EMPHASES}
                selected={form.emphasis}
                onToggle={(id) => setMultiChip('emphasis', id)}
              />
              <div className="add-paper__toggles">
                <label className="graph-controls__toggle">
                  <input type="checkbox" checked={form.formalConcepts} onChange={(e) => setField('formalConcepts', e.target.checked)} />
                  <span>Contains formal concepts</span>
                </label>
                <label className="graph-controls__toggle">
                  <input type="checkbox" checked={form.algorithms} onChange={(e) => setField('algorithms', e.target.checked)} />
                  <span>Contains an algorithm</span>
                </label>
                <label className="graph-controls__toggle">
                  <input type="checkbox" checked={form.hypothesis} onChange={(e) => setField('hypothesis', e.target.checked)} />
                  <span>Contains a statistical hypothesis</span>
                </label>
              </div>
              {form.hypothesis && (
                <div className="add-paper__grid add-paper__grid--spaced">
                  <div className="add-paper__field">
                    <label className="filters-panel__label">Independent variables</label>
                    <input className="toolbar__search" value={form.independentVariables} onChange={(e) => setField('independentVariables', e.target.value)} />
                  </div>
                  <div className="add-paper__field">
                    <label className="filters-panel__label">Dependent variables</label>
                    <input className="toolbar__search" value={form.dependentVariables} onChange={(e) => setField('dependentVariables', e.target.value)} />
                  </div>
                </div>
              )}

              <h3 className="add-paper__section">Design, Evaluation &amp; Evidence</h3>
              {codeWithOther('researchMethod')}
              {codeWithOther('evaluationMethod')}
              <ChipSelect label="Data Type" options={codeOptions(papers, CODE_GETTERS.dataType, form.dataType)} selected={form.dataType} onToggle={(id) => setMultiChip('dataType', id)} />
              {codeWithOther('threatsToValidity')}

              <div className="add-paper__toggles">
                <label className="graph-controls__toggle">
                  <input type="checkbox" checked={form.implementationExistence} onChange={(e) => setField('implementationExistence', e.target.checked)} />
                  <span>Implementation exists</span>
                </label>
                <label className="graph-controls__toggle">
                  <input type="checkbox" checked={form.implementationAvailability} onChange={(e) => setField('implementationAvailability', e.target.checked)} />
                  <span>Publicly available</span>
                </label>
              </div>
              </fieldset>

              <div className="modal__actions">
                {editing ? (
                  <button className="btn btn--ghost" onClick={onClose}>Cancel</button>
                ) : (
                  <button className="btn btn--ghost" onClick={() => { setError(null); setStep('input'); }}>← Back</button>
                )}
                <div className="add-paper__nav">
                  {isBatch && (
                    <>
                      <button className="btn btn--secondary" onClick={() => goTo(current - 1)} disabled={current === 0}>Previous</button>
                      {!onLastDraft && <button className="btn btn--primary" onClick={() => goTo(current + 1)}>Next</button>}
                    </>
                  )}
                  <button className={`btn ${isBatch && !onLastDraft ? 'btn--secondary' : 'btn--primary'}`} onClick={handleSubmit} disabled={submitting || (!isBatch && draft.added)}>
                    {submitting ? (editing ? 'Saving…' : 'Adding…') : editing ? 'Save changes' : isBatch ? `Add ${readyCount} ready ${readyCount === 1 ? 'paper' : 'papers'}` : 'Add Paper'}
                  </button>
                </div>
              </div>
            </>
          )}

          {step === 'success' && addedPapers.length > 0 && (
            <>
              <p className="add-paper__hint">
                {addedPapers.length === 1 ? 'Added' : `Added ${addedPapers.length} papers`} to your browser. You'll find{' '}
                {addedPapers.length === 1 ? 'it' : 'them'} pinned at the top of the papers list on the right, and marked
                with a dashed ring in the visualizations and graph.
              </p>
              {addedPapers.length > 1 && (
                <>
                  <p className="add-paper__hint">
                    Choose which papers to propose for the shared dataset. They are saved together in one JSON file, which
                    you attach to the pre-filled issue.
                  </p>
                  <ul className="add-paper__added">
                    {addedPapers.map((p) => (
                      <li key={p._userKey}>
                        <label className="add-paper__added-item">
                          <input
                            type="checkbox"
                            checked={proposeKeys.has(p._userKey)}
                            onChange={() => toggleProposal(p._userKey)}
                          />
                          <span>{p.metadata.title}</span>
                        </label>
                      </li>
                    ))}
                  </ul>
                </>
              )}
              <p className="add-paper__note">
                {addedPapers.length === 1 ? "It's" : "They're"} only in your browser, though. Nobody else sees{' '}
                {addedPapers.length === 1 ? 'it' : 'them'}, and {addedPapers.length === 1 ? "it's" : "they're"} not part of
                the shared dataset. If you'd like {addedPapers.length === 1 ? 'it' : 'them'} considered for the real corpus,
                open an issue with the details pre-filled. It only takes one click, and it would make us happy. A maintainer
                can review and fold {addedPapers.length === 1 ? 'it' : 'them'} into the coding spreadsheet.
              </p>
              {pending.length > 0 && (
                <p className="add-paper__warning">
                  {pending.length} {pending.length === 1 ? 'paper still needs' : 'papers still need'} coding and {pending.length === 1 ? 'was' : 'were'} not added.
                </p>
              )}
              <div className="modal__actions">
                <button className="btn btn--ghost" onClick={onClose}>Done</button>
                <div className="add-paper__nav">
                  {pending.length > 0 && (
                    <button className="btn btn--secondary" onClick={continueRemaining}>
                      Code the remaining {pending.length} →
                    </button>
                  )}
                  {addedPapers.length === 1 ? (
                    <button
                      className="btn btn--primary"
                      onClick={() => {
                        proposePapers(addedPapers).then(() => onAdded(null));
                        onClose();
                      }}
                    >
                      Propose for shared dataset →
                    </button>
                  ) : (
                    <button className="btn btn--primary" onClick={handleProposeAll} disabled={toPropose.length === 0}>
                      Propose {toPropose.length} for shared dataset →
                    </button>
                  )}
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </>
  );
}
