import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { ThemeProvider } from '@/lib/theme';
import { FilterProvider } from '@/lib/filterState';
import { ShapesProvider } from '@/lib/shapes';
import { CodingProvider, useCoding } from '@/lib/codingState';
import PapersPage from '@/views/PapersPage';
import PaperDetailPage from '@/views/PaperDetailPage';
import RelationshipsPage from '@/views/RelationshipsPage';
import ComparePage from '@/views/ComparePage';
import AboutPage from '@/views/AboutPage';
import AnalysisPage from '@/views/AnalysisPage';

import '@/styles/global.css';
import './styles/app.css';

const basename = import.meta.env.BASE_URL;

// A new coding version (papers of the visitor's review saved) remounts the
// pages, so they load the coded papers again. Filters are kept.
function AppRoutes() {
  const { version } = useCoding();
  return (
    <Routes key={version}>
      <Route path="/" element={<PapersPage />} />
      <Route path="/papers/*" element={<PaperDetailPage />} />
      <Route path="/relationships" element={<RelationshipsPage />} />
      <Route path="/compare" element={<ComparePage />} />
      <Route path="/analysis" element={<AnalysisPage />} />
      <Route path="/about" element={<AboutPage />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}

export default function App() {
  return (
    <ThemeProvider>
      <ShapesProvider>
      <BrowserRouter basename={basename}>
        <FilterProvider>
        <CodingProvider>
          <AppRoutes />
        </CodingProvider>
        </FilterProvider>
      </BrowserRouter>
      </ShapesProvider>
    </ThemeProvider>
  );
}
