import { DIMENSIONS, MISSING, unitValues } from './analysis';

const paperValues = (paper, dim) =>
  unitValues({ paper, artifacts: paper.contribution?.artifacts || [] }, dim).filter((v) => v !== MISSING);

// The dimensions marked "similarity" in the schema.
export const SIMILARITY_DIMENSIONS = DIMENSIONS.filter((d) => !d.numeric && d.uses.includes('similarity'));

export function buildSimilarity(papers) {
  const values = new Map(papers.map((p) => [p._id, SIMILARITY_DIMENSIONS.map((d) => paperValues(p, d))]));
  const weights = SIMILARITY_DIMENSIONS.map((_, d) => {
    const df = new Map();
    let coded = 0;
    papers.forEach((p) => {
      const vs = values.get(p._id)[d];
      if (!vs.length) return;
      coded += 1;
      new Set(vs).forEach((v) => df.set(v, (df.get(v) || 0) + 1));
    });
    return new Map([...df].map(([v, n]) => [v, Math.log(1 + coded / n)]));
  });

  const compare = (a, b) => {
    const va = values.get(a._id);
    const vb = values.get(b._id);
    const attributes = [];
    SIMILARITY_DIMENSIONS.forEach((dim, d) => {
      if (!va[d].length || !vb[d].length) return;
      const sa = new Set(va[d]);
      const sb = new Set(vb[d]);
      const w = (v) => weights[d].get(v) || 0;
      const shared = [...sa].filter((v) => sb.has(v));
      const union = new Set([...sa, ...sb]);
      const total = [...union].reduce((s, v) => s + w(v), 0);
      const score = total ? shared.reduce((s, v) => s + w(v), 0) / total : 0;
      attributes.push({
        key: dim.key,
        score,
        shared,
        onlyA: [...sa].filter((v) => !sb.has(v)),
        onlyB: [...sb].filter((v) => !sa.has(v)),
      });
    });
    const score = attributes.length ? attributes.reduce((s, x) => s + x.score, 0) / attributes.length : 0;
    return { score, attributes };
  };

  const mostSimilar = (target, candidates) => candidates
    .filter((p) => p._id !== target._id)
    .map((p) => ({ paper: p, ...compare(target, p) }))
    .filter((r) => r.attributes.length > 0)
    .sort((x, y) => y.score - x.score);

  return { compare, mostSimilar };
}
