import { createContext, lazy, Suspense, useCallback, useContext, useMemo, useState } from 'react';

const CodePaperModal = lazy(() => import('@/components/CodePaperModal'));

const CodingContext = createContext({
  version: 0,
  openCoding: () => {},
});

/**
 * Opens the coding form of the visitor's own review from anywhere (review
 * bar, paper detail). The form lives here, outside the pages, because
 * saving changes `version`, and App remounts the pages on a new version so
 * they load the coded papers again.
 */
export function CodingProvider({ children }) {
  const [version, setVersion] = useState(0);
  const [coding, setCoding] = useState(null);

  // index: the paper's place in the review, or null for the next paper
  // that is not fully coded.
  const openCoding = useCallback((index = null) => setCoding({ index }), []);
  const refreshIf = (changed) => { if (changed) setVersion((v) => v + 1); };
  const closeCoding = (changed) => { setCoding(null); refreshIf(changed); };

  const value = useMemo(() => ({ version, openCoding }), [version, openCoding]);

  return (
    <CodingContext.Provider value={value}>
      {children}
      <Suspense fallback={null}>
        {coding && <CodePaperModal startIndex={coding.index} onClose={closeCoding} />}
      </Suspense>
    </CodingContext.Provider>
  );
}

export const useCoding = () => useContext(CodingContext);
