/**
 * Helpers for the fields of the paper forms (Add Paper, the coding form).
 */

/** A comma-separated text as a list of trimmed, non-empty entries. */
export function splitList(s) {
  return (s || '').split(',').map((v) => v.trim()).filter(Boolean);
}

/** A list as comma-separated text, the reverse of splitList. */
export const joinList = (list) => (Array.isArray(list) ? list.join(', ') : list || '');

/** Adds the value to the list, or removes it when it is there. */
export function toggleMulti(list, value) {
  return list.includes(value) ? list.filter((v) => v !== value) : [...list, value];
}

/** Single-select "toggle": picking a new value replaces the selection;
 * picking the already-active one clears it. Kept as a 0-or-1-item array so
 * the record shape matches the schema's array fields either way. */
export function toggleSingle(list, value) {
  return list[0] === value ? [] : [value];
}

/** Whether a chosen value is the "Other" value, which needs a name. */
export const isOtherId = (id) => typeof id === 'string' && /^other$/i.test(id);

/** Names typed for "Other" values are offered as chips of their own the
 * next time, with ids "other:<name>". Several names in one text are
 * separated by NAME_SEPARATOR. */
export const NAMED = 'other:';
export const NAME_SEPARATOR = '; ';
export const isNamed = (id) => typeof id === 'string' && id.startsWith(NAMED);
export const splitNames = (s) => (typeof s === 'string' ? s : '').split(';').map((n) => n.trim()).filter(Boolean);

/** The distinct names (ignoring case), most used first. `keep` names are
 * listed even when no record uses them. */
export function rankNames(names, keep = []) {
  const byKey = new Map();
  const count = (name, n) => {
    const k = name.toLowerCase();
    const entry = byKey.get(k) || { name, count: 0 };
    entry.count += n;
    byKey.set(k, entry);
  };
  names.forEach((n) => count(n, 1));
  keep.forEach((n) => count(n, 0));
  return [...byKey.values()]
    .sort((x, y) => y.count - x.count || x.name.localeCompare(y.name))
    .map(({ name }) => name);
}

/** Chips for named "Other" values. */
export const namedChips = (names) => names.map((name) => ({ id: `${NAMED}${name}`, label: name }));
