import Field from './Field';
import { DETAIL, fieldShows } from '@/lib/detail';

/**
 * Renders one entry of contribution.artifacts: the per-artifact fields of
 * the schema, in schema order (see lib/detail.js).
 */
export default function ArtifactCard({ artifact }) {
  return (
    <div className="artifact-card">
      {DETAIL.artifacts.fields.filter((f) => fieldShows(f, artifact)).map((f) => (
        <Field key={f.path} label={f.label} value={f.read(artifact)} />
      ))}
    </div>
  );
}
