import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import Header from '@/components/Header';
import PaperDetailPanel from '@/components/PaperDetailPanel';
import SimilarPapers from '@/components/SimilarPapers';
import FilterBar from '@/components/FilterBar';
import { matchesFilters, activeFilterCount } from '@/lib/facets';
import { useFilters } from '@/lib/filterState';
import { loadPapers, loadConfig, loadKeywordLinks } from '@/lib/data';
import { buildGraphData, createRelationshipGraph, EDGE_STYLE } from '@/viz/graph';
import { attachBubbleMotion } from '@/lib/bubbleMotion';
import { humanize } from '@/lib/humanize';
import { makeColorFor, makeShapeFor } from '@/lib/colors';
import { ShapesToggle, useShapes } from '@/lib/shapes';
import { DIMENSIONS, MISSING, choiceProfile, unitValues } from '@/lib/analysis';
import { useLocation, useSearchParams } from 'react-router-dom';

const SINGLE_CHOICE_MAX_MULTI = 0.1;
const MAX_HULLS = 12;
// The default group is the Overview's default tiles, when it can group.
const DEFAULT_HULL = DIMENSIONS.find((d) => d.uses.includes('overview.defaultTile'))?.key;
const NO_GROUPS = 'none';
const MAX_EDGES_STEPS = 12;
const DEFAULT_MAX_EDGES = MAX_EDGES_STEPS;
const KEYWORD_EDGES = 'keywords';

const paperValues = (paper, dim) =>
  unitValues({ paper, artifacts: paper.contribution?.artifacts || [] }, dim).filter((v) => v !== MISSING);

export default function RelationshipsPage() {
  const [papers, setPapers] = useState(null);
  const [config, setConfig] = useState(null);
  const [keywordLinks, setKeywordLinks] = useState([]);
  const containerRef = useRef(null);
  const vizRef = useRef(null);

  const [showLabels, setShowLabels] = useState(true);
  const [showUnconnected, setShowUnconnected] = useState(false);
  const [maxEdges, setMaxEdges] = useState(DEFAULT_MAX_EDGES);
  const edgeLimit = maxEdges > MAX_EDGES_STEPS - 1 ? Infinity : maxEdges;
  const [similarityPercentile, setSimilarityPercentile] = useState(0.98);
  const [nodeSpacing, setNodeSpacing] = useState(1.5);

  const [hovered, setHovered] = useState(null);
  const { filters } = useFilters();
  const visiblePapers = useMemo(() => {
    if (!papers || activeFilterCount(filters) === 0) return papers;
    return papers.filter((p) => matchesFilters(p, filters));
  }, [papers, filters]);
  const [selectedPaperId, setSelectedPaperId] = useState(null);
  const [similarSize, setSimilarSize] = useState(10);
  const location = useLocation();

  useEffect(() => {
    Promise.all([loadPapers(), loadConfig(), loadKeywordLinks()]).then(([p, c, kl]) => {
      setPapers(p);
      setConfig(c);
      setKeywordLinks(kl);
    });
  }, []);

  const artifactColors = useMemo(() => {
    const map = {};
    (config?.typesOfArtifact || []).forEach((t) => {
      map[t.id] = t.color;
    });
    return map;
  }, [config]);

  const dimOptions = useMemo(() => {
    if (!papers) return { hull: [] };
    const hull = [];
    DIMENSIONS.filter((d) => !d.numeric && d.uses.includes('metagraph.groups')).forEach((d) => {
      const c = choiceProfile(papers, d);
      if (!c.coded || c.counts.size < 2) return;
      const option = { key: d.key, label: humanize(d.key), counts: c.counts };
      if (c.multiShare <= SINGLE_CHOICE_MAX_MULTI && c.counts.size <= MAX_HULLS) hull.push(option);
    });
    return { hull };
  }, [papers]);

  const [params, setParams] = useSearchParams();
  const setParam = (name, value, fallback) => setParams((prev) => {
    const p = new URLSearchParams(prev);
    if (value === fallback) p.delete(name); else p.set(name, value);
    return p;
  }, { replace: true });

  const showSimilar = (id, size) => {
    setParam('similar', id, null);
    setSimilarSize(size);
    setTimeout(() => document.getElementById('similar')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
  };

  useEffect(() => {
    if (!papers || location.hash !== '#similar') return;
    requestAnimationFrame(() => document.getElementById('similar')?.scrollIntoView({ block: 'start' }));
  }, [papers, location.hash]);

  const defaultHull = dimOptions.hull.some((o) => o.key === DEFAULT_HULL) ? DEFAULT_HULL : dimOptions.hull[0]?.key;
  const groupParam = params.get('groups');
  const hullKey = groupParam === NO_GROUPS || dimOptions.hull.some((o) => o.key === groupParam) ? groupParam : defaultHull;
  const hullOption = dimOptions.hull.find((o) => o.key === hullKey);
  const edgeLabel = 'Shared Keywords';

  const colorFor = useMemo(() => (config ? makeColorFor(config, papers) : () => null), [config, papers]);
  const { shapes } = useShapes();
  const shapeFor = useMemo(() => (config && shapes ? makeShapeFor(config, papers) : () => null), [config, papers, shapes]);

  const groups = useMemo(() => {
    if (!hullOption || !config) return [];
    const configured = { type_of_artifact: config.typesOfArtifact, type_of_inquiry: config.typesOfInquiry }[hullOption.key] || [];
    return [...hullOption.counts.entries()]
      .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
      .map(([id]) => ({
        id,
        label: configured.find((t) => t.id === id)?.label || humanize(id),
        color: colorFor(hullOption.key, id) || '#88c0d0',
        shape: shapeFor(hullOption.key, id),
      }));
  }, [hullOption, config, colorFor, shapeFor]);

  const handleZoomIn = useCallback(() => vizRef.current?.zoomIn(), []);
  const handleZoomOut = useCallback(() => vizRef.current?.zoomOut(), []);

  useEffect(() => {
    const handleKeyDown = (e) => {
      const active = document.activeElement;
      if (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' || active.isContentEditable) return;
      if (e.key === '+' || e.key === '=') { e.preventDefault(); handleZoomIn(); }
      else if (e.key === '-' || e.key === '_') { e.preventDefault(); handleZoomOut(); }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleZoomIn, handleZoomOut]);

  useEffect(() => {
    if (!visiblePapers || !containerRef.current || !config || visiblePapers.length === 0) return undefined;
    const hullDim = DIMENSIONS.find((d) => d.key === hullKey);
    const groupColor = Object.fromEntries(groups.map((g) => [g.id, g.color]));
    const groupShape = Object.fromEntries(groups.map((g) => [g.id, g.shape]));
    const data = buildGraphData(visiblePapers, {
      groupOf: (paper) => (hullDim ? paperValues(paper, hullDim)[0] : undefined),
      colorOfGroup: (id) => groupColor[id],
      shapeOfGroup: (id) => groupShape[id],
      edges: KEYWORD_EDGES,
      similarityPercentile,
      maxEdgesPerPaper: edgeLimit,
      precomputedKeywordLinks: keywordLinks,
    });
    if (!showUnconnected) {
      const connected = new Set(data.links.flatMap((l) => [l.source, l.target]));
      data.nodes = data.nodes.filter((n) => connected.has(n.id));
    }
    const present = new Set(data.nodes.map((n) => n.cluster));
    vizRef.current = createRelationshipGraph(containerRef.current, data, {
      groups: groups.filter((g) => present.has(g.id)),
      showLabels,
      showClusters: hullKey !== NO_GROUPS,
      nodeSpacing,
      onNodeClick: (id) => showSimilar(id, 5),
      onNodeHover: setHovered,
      onNodeLeave: () => setHovered(null),
    });
    return () => vizRef.current?.destroy();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [visiblePapers, config, groups, hullKey, similarityPercentile, edgeLimit, nodeSpacing, keywordLinks, showUnconnected]);

  useEffect(() => {
    if (!papers || !config || !containerRef.current) return undefined;
    return attachBubbleMotion(containerRef.current, { selector: 'g.graph-node', anchor: '.node-circle', maxPull: 5, radius: 130 });
  }, [papers, config]);

  useEffect(() => {
    vizRef.current?.setShowLabels(showLabels);
  }, [showLabels]);

  if (!papers || !config) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  const labels = config.visualization?.labels || {};

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content">
        <h1>{labels.graphTitle || 'Paper Metagraph'}</h1>
        {labels.graphDescription && <p className="graph-page__description">{labels.graphDescription}</p>}

        <div className="graph-layout">
        <div className="graph-frame">
        <div className="graph-controls">
          <div className="graph-controls__group">
            <label className="ax-field graph-controls__select">
              <span className="ax-field__label">Groups</span>
              <select className="ax-select" value={hullKey || NO_GROUPS} onChange={(e) => setParam('groups', e.target.value, defaultHull)}
                title="Single-choice attributes: every paper belongs to exactly one group, outlined by a convex hull">
                {dimOptions.hull.map((o) => <option key={o.key} value={o.key}>{o.label}</option>)}
                <option value={NO_GROUPS}>None</option>
              </select>
            </label>
          </div>
          <div className="graph-controls__group graph-controls__group--tune">
            <div className="graph-controls__slider">
              <label>Similarity: top {Math.round((1 - similarityPercentile) * 100)}%</label>
              <input
                type="range"
                min="0.7"
                max="0.98"
                step="0.01"
                value={similarityPercentile}
                onChange={(e) => setSimilarityPercentile(parseFloat(e.target.value))}
              />
            </div>
            <div className="graph-controls__slider">
              <label htmlFor="max-edges">Max edges per paper: {edgeLimit === Infinity ? 'no limit' : edgeLimit}</label>
              <input
                id="max-edges"
                type="range"
                min="1"
                max={MAX_EDGES_STEPS}
                step="1"
                value={maxEdges}
                onChange={(e) => setMaxEdges(parseInt(e.target.value, 10))}
                title="Upper limit of edges ending at one paper. The last step removes the limit."
              />
            </div>
            <div className="graph-controls__slider">
              <label>Spacing: {nodeSpacing.toFixed(1)}x</label>
              <input
                type="range"
                min="0.5"
                max="3.0"
                step="0.1"
                value={nodeSpacing}
                onChange={(e) => setNodeSpacing(parseFloat(e.target.value))}
              />
            </div>
            <label className="graph-controls__toggle">
              <input type="checkbox" checked={showLabels} onChange={(e) => setShowLabels(e.target.checked)} />
              <span>Show Labels</span>
            </label>
            <label className="graph-controls__toggle">
              <input type="checkbox" checked={showUnconnected} onChange={(e) => setShowUnconnected(e.target.checked)} />
              <span>Show Unconnected</span>
            </label>
            <ShapesToggle />
          </div>
        </div>

        <div className="graph-canvas-wrap">
          <div className="graph-page__canvas" ref={containerRef} />
          <div className="graph-zoom" role="group" aria-label="Zoom">
            <button className="graph-controls__btn" onClick={handleZoomIn} title="Zoom in (+). You can also scroll to zoom and drag nodes." aria-label="Zoom in">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="11" cy="11" r="8" />
                <line x1="21" y1="21" x2="16.65" y2="16.65" />
                <line x1="11" y1="8" x2="11" y2="14" />
                <line x1="8" y1="11" x2="14" y2="11" />
              </svg>
            </button>
            <button className="graph-controls__btn" onClick={handleZoomOut} title="Zoom out (−). You can also scroll to zoom and drag nodes." aria-label="Zoom out">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="11" cy="11" r="8" />
                <line x1="21" y1="21" x2="16.65" y2="16.65" />
                <line x1="8" y1="11" x2="14" y2="11" />
              </svg>
            </button>
          </div>
          {visiblePapers.length === 0 && (
            <div className="graph-empty empty-state">
              <p>No papers match the current filters.</p>
            </div>
          )}

          {hovered && (
            <div className="graph-hover-card">
              {hovered.userAdded && <span className="user-added-badge">+ Added by you</span>}
              <h4>{hovered.title || 'Anonymized paper'}</h4>
              <div className="graph-hover-card__meta">
                {hovered.typeOfArtifact.map((t) => (
                  <span key={t} style={{ color: artifactColors[t] }}>{humanize(t)}</span>
                ))}
                {hovered.year && <span>· {hovered.year}</span>}
              </div>
              {hovered.keywords.length > 0 && (
                <div className="graph-hover-card__tags">
                  {hovered.keywords.slice(0, 6).map((k) => (
                    <span key={k} className="chip chip--sm">{k}</span>
                  ))}
                </div>
              )}
              <p className="graph-hover-card__hint">
                {hovered.degree} connection{hovered.degree !== 1 ? 's' : ''}
              </p>
            </div>
          )}
        </div>

        <div className="graph-legend">
          <span className="graph-legend__title">Relationships</span>
          <div className="graph-legend__items">
            {edgeLabel && (
              <span className="graph-legend__item">
                <svg width="24" height="10" viewBox="0 0 24 10">
                  <line x1="0" y1="5" x2="24" y2="5" stroke={EDGE_STYLE.color} strokeWidth={EDGE_STYLE.strokeWidth} />
                </svg>
                {edgeLabel}
              </span>
            )}
          </div>
        </div>
        </div>

        <FilterBar papers={papers} config={config} orientation="vertical" />
        </div>

        <SimilarPapers
          papers={papers}
          candidates={visiblePapers}
          targetId={params.get('similar')}
          onTargetChange={(id) => setParam('similar', id, null)}
          size={similarSize}
          onSizeChange={setSimilarSize}
          onOpen={setSelectedPaperId}
          filtered={activeFilterCount(filters) > 0}
        />
      </main>

      {selectedPaperId && (
        <PaperDetailPanel
          paperId={selectedPaperId}
          papers={papers}
          config={config}
          onClose={() => setSelectedPaperId(null)}
          onSelectPaper={setSelectedPaperId}
          onRemoved={() => loadPapers().then(setPapers)}
          onFindSimilar={(id) => {
            setSelectedPaperId(null);
            showSimilar(id, similarSize);
          }}
        />
      )}
    </div>
  );
}
