import Field from './Field';
import ArtifactCard from './ArtifactCard';
import { humanize } from '@/lib/humanize';
import { getArtifactTypes } from '@/lib/filters';
import { DETAIL, fieldShows, sectionShows } from '@/lib/detail';
import { timelineRowOf, yearOf } from '@/lib/roles';
import { useCoding } from '@/lib/codingState';
import { CODING, codingStatusOf } from '@/lib/review';

function formatDoiUrl(doiOrUrl) {
  if (!doiOrUrl) return null;
  if (doiOrUrl.startsWith('http://') || doiOrUrl.startsWith('https://')) return doiOrUrl;
  return `https://doi.org/${doiOrUrl}`;
}

const RELATIONSHIP_LABELS = {
  'shared-keywords': 'Shared Keywords',
};

/**
 * Full rendering of a paper's schema-nested record. Shared between the
 * full-page detail view and the slide-over panel used from the graph, so
 * both stay in sync.
 */
export default function PaperDetailContent({ paper, artifactConfig, relatedPapers = [], onRelatedClick, onRemove, onEdit, onPropose, onFindSimilar }) {
  const { metadata = {}, contribution = {} } = paper;
  const artifacts = contribution.artifacts || [];
  const { openCoding } = useCoding();
  // Papers of the visitor's own review carry their place in it.
  const reviewIndex = paper._reviewIndex;
  const status = reviewIndex !== undefined ? codingStatusOf(paper) : null;

  return (
    <>
      {status && (
        <div className={`user-added-banner coding-badge coding-badge--${status}`}>
          <span>{CODING[status]}</span>
          <div className="user-added-banner__actions">
            <button type="button" className="btn btn--primary btn--sm" onClick={() => openCoding(reviewIndex)}>
              Code This Paper
            </button>
          </div>
        </div>
      )}
      {paper._userAdded && (
        <div className="user-added-banner">
          <span>
            + Added by you — this paper lives only in your browser.
            {paper._proposedAt && ` Proposed ${new Date(paper._proposedAt).toLocaleDateString()}${paper._editedAt > paper._proposedAt ? ', changed since' : ''}.`}
          </span>
          <div className="user-added-banner__actions">
            {onEdit && (
              <button type="button" className="btn btn--ghost btn--sm" onClick={onEdit}>
                Edit
              </button>
            )}
            {onPropose && (
              <button type="button" className="btn btn--ghost btn--sm" onClick={onPropose}>
                Propose for shared dataset
              </button>
            )}
            {onRemove && (
              <button type="button" className="btn btn--ghost btn--sm" onClick={onRemove}>
                Remove
              </button>
            )}
          </div>
        </div>
      )}
      <div className="paper-detail__badges">
        {getArtifactTypes(paper).map((t) => (
          <span
            key={t}
            className="paper-card__badge"
            style={{ '--inquiry-color': artifactConfig[t]?.color || '#88c0d0' }}
          >
            {artifactConfig[t]?.label || humanize(t)}
          </span>
        ))}
      </div>

      <h1 className="paper-detail__title">{metadata.title || 'Anonymized paper'}</h1>
      <p className="paper-detail__meta">
        {[metadata.authors?.join(', '), [metadata.conference_abbreviation, yearOf(paper)].filter(Boolean).join(' '), timelineRowOf(paper)].filter(Boolean).join(' · ')}
      </p>
      <div className="paper-detail__actions">
        {metadata.title && metadata.doi_or_url && (
          <a
            className="btn btn--secondary btn--sm"
            href={formatDoiUrl(metadata.doi_or_url)}
            target="_blank"
            rel="noopener noreferrer"
          >
            View Paper →
          </a>
        )}
        {metadata.title && onFindSimilar && (
          <button type="button" className="btn btn--secondary btn--sm" onClick={() => onFindSimilar(paper._id)}>
            Most Similar Papers →
          </button>
        )}
      </div>

      <Field
        label="Conference"
        value={[metadata.conference_name, metadata.conference_abbreviation && `(${metadata.conference_abbreviation})`].filter(Boolean).join(' ')}
      />
      {DETAIL.paperFields.filter((f) => fieldShows(f, paper)).map((f) => (
        <Field key={f.path} label={f.label} value={f.read(paper)} />
      ))}

      {DETAIL.sections.filter((section) => sectionShows(section, paper)).map((section) => (
        <section key={section.title} className="detail-section">
          <h2 className="detail-section__title">{section.title}</h2>
          {section.fields.filter((f) => fieldShows(f, paper)).map((f) => (
            <Field key={f.path} label={f.label} value={f.read(paper)} />
          ))}
        </section>
      ))}

      {artifacts.length > 0 && (
        <section className="detail-section">
          <h2 className="detail-section__title">{DETAIL.artifacts.title}</h2>
          <div className="artifact-grid">
            {artifacts.map((artifact, i) => (
              <ArtifactCard key={i} artifact={artifact} />
            ))}
          </div>
        </section>
      )}

      {relatedPapers.length > 0 && (
        <section className="detail-section">
          <h2 className="detail-section__title">Related Entries</h2>
          <div className="related-papers">
            {relatedPapers.map((related) => (
              <button
                key={related._id}
                type="button"
                className="related-paper"
                onClick={() => onRelatedClick?.(related._id)}
              >
                <span className="related-paper__title">{related.metadata.title || 'Anonymized paper'}</span>
                <span className="related-paper__relationship">{RELATIONSHIP_LABELS[related.relationship]}</span>
              </button>
            ))}
          </div>
        </section>
      )}
    </>
  );
}
