import { applyMapping, extractAttributes, suggestMapping } from '@/lib/schemaMapping';

const DRAFT_KEY = 'ariadne-lit:schema-draft';

export const BUILDER_KINDS = [
  { key: 'single', label: 'Single choice', hint: 'One value from a fixed list, e.g. a track.' },
  { key: 'multi', label: 'Multiple choice', hint: 'Any number of values from a fixed list, e.g. research methods.' },
  { key: 'boolean', label: 'Yes / no', hint: 'Whether something applies, e.g. data is available.' },
  { key: 'number', label: 'Number', hint: 'A count or measure, e.g. number of participants.' },
  { key: 'text', label: 'Text', hint: 'Free text, e.g. the research question.' },
  { key: 'list', label: 'Free list', hint: 'Any number of free-text entries.' },
];

/** Attributes every compatible schema has; the views rely on these paths. */
export const FIXED_ATTRIBUTES = [
  { path: 'metadata.title', label: 'Title', kind: 'Text', note: 'Shown on every paper card.' },
  { path: 'metadata.authors', label: 'Authors', kind: 'Free list', note: 'Shown on every paper card.' },
  { path: 'metadata.doi_or_url', label: 'DOI or URL', kind: 'Text', note: 'Links to the paper.' },
  { path: 'metadata.year', label: 'Year', kind: 'Number', note: 'Role: Year.' },
  { path: 'contribution.keywords', label: 'Keywords', kind: 'Free list', note: 'Role: Keywords.' },
];

const RESERVED = new Set(['keywords']);

const CHOICE = new Set(['single', 'multi']);

let nextId = 1;
export const newAttribute = () => ({ id: `a${Date.now().toString(36)}${nextId++}`, name: '', kind: 'multi', values: '', allowOther: false, description: '' });

export const emptyDraft = () => ({ title: '', description: '', attributes: [newAttribute()] });

export const toKey = (name) => name.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');

export const OTHER_VALUE = 'other';

const isOther = (v) => /^other$/i.test(v);

/** The listed values, without "other", which allowOther adds itself. */
export const parseValues = (text) => [...new Set(text.split(/[,\n]/).map((v) => v.trim()).filter((v) => v && !isOther(v)))];

export const otherKeyOf = (key) => `${key}_other`;

const offersOther = (a) => CHOICE.has(a.kind) && Boolean(a.allowOther);

/** Returns { [attributeId]: message } plus `_form` for problems with the whole draft. */
export function validateDraft(draft) {
  const problems = {};
  if (!draft.title.trim()) problems._title = 'Give the schema a title.';
  const seen = new Set();
  const otherKeys = new Set();
  draft.attributes.forEach((a) => {
    if (offersOther(a) && toKey(a.name)) otherKeys.add(otherKeyOf(toKey(a.name)));
  });
  draft.attributes.forEach((a) => {
    const key = toKey(a.name);
    if (!key) {
      problems[a.id] = 'Enter a name with at least one letter or digit.';
      return;
    }
    if (RESERVED.has(key)) {
      problems[a.id] = `"${key}" is already part of every schema. Choose another name.`;
      return;
    }
    if (seen.has(key)) {
      problems[a.id] = `Another attribute is also called "${key}".`;
      return;
    }
    if (otherKeys.has(key)) {
      problems[a.id] = `"${key}" holds the text of an "Other" value. Choose another name.`;
      return;
    }
    seen.add(key);
    const minimum = offersOther(a) ? 1 : 2;
    if (CHOICE.has(a.kind) && parseValues(a.values).length < minimum) {
      problems[a.id] = minimum === 1 ? 'List at least one value besides "Other".' : 'List at least two values, separated by commas.';
    }
  });
  if (!draft.attributes.length) problems._form = 'Add at least one attribute to code your papers by.';
  return problems;
}

function attributeNode(a) {
  const values = [...parseValues(a.values), ...(offersOther(a) ? [OTHER_VALUE] : [])];
  const description = a.description.trim() || undefined;
  switch (a.kind) {
    case 'single': return { type: 'string', enum: values, description };
    case 'multi': return { type: 'array', items: { type: 'string', enum: values }, uniqueItems: true, description };
    case 'boolean': return { type: 'boolean', description };
    case 'number': return { type: 'number', description };
    case 'list': return { type: 'array', items: { type: 'string' }, description };
    default: return { type: 'string', description };
  }
}

/** JSON Schema rule: choosing "other" makes the companion text required. */
function otherRule(a, key) {
  const otherKey = otherKeyOf(key);
  const chosen = a.kind === 'multi' ? { contains: { const: OTHER_VALUE } } : { const: OTHER_VALUE };
  return {
    if: { properties: { [key]: chosen }, required: [key] },
    then: { required: [otherKey], properties: { [otherKey]: { minLength: 1 } } },
  };
}

function rawSchema(draft) {
  const props = {};
  const rules = [];
  draft.attributes.forEach((a) => {
    const key = toKey(a.name);
    props[key] = attributeNode(a);
    if (offersOther(a)) {
      props[otherKeyOf(key)] = {
        type: 'string',
        description: `Name of the other ${a.name.trim().toLowerCase()}; required when ${key} ${a.kind === 'multi' ? 'includes' : 'is'} "${OTHER_VALUE}"`,
      };
      rules.push(otherRule(a, key));
    }
  });
  const contribution = {
    type: 'object',
    properties: {
      keywords: { type: 'array', items: { type: 'string' }, description: 'Keywords of the paper' },
      ...props,
    },
    ...(rules.length ? { allOf: rules } : {}),
  };
  return {
    $schema: 'http://json-schema.org/draft-07/schema#',
    title: draft.title.trim(),
    ...(draft.description.trim() ? { description: draft.description.trim() } : {}),
    type: 'object',
    required: ['metadata', 'contribution'],
    properties: {
      metadata: {
        type: 'object',
        required: ['title', 'authors', 'doi_or_url', 'year'],
        properties: {
          title: { type: 'string', description: 'Paper title' },
          authors: { type: 'array', items: { type: 'string' }, description: 'Paper authors' },
          doi_or_url: { type: 'string', description: 'DOI or URL to the paper' },
          year: { type: 'integer', description: 'Publication year' },
        },
      },
      contribution,
    },
  };
}

/** Builds the schema with x-ariadne annotations suggested for each attribute,
 * the same way an uploaded schema is pre-filled. */
export function buildSchema(draft, meta = null) {
  const schema = JSON.parse(JSON.stringify(rawSchema(draft)));
  const attributes = extractAttributes(schema);
  const mapping = suggestMapping(attributes);
  mapping.roles = { year: 'metadata.year', keywords: 'contribution.keywords' };
  mapping.uses['contribution.keywords'] = new Set();
  return applyMapping(schema, attributes, mapping, meta);
}

export const schemaFileName = (draft) => `${toKey(draft.title) || 'schema'}.schema.json`;

export function loadDraft() {
  try {
    const raw = localStorage.getItem(DRAFT_KEY);
    const draft = raw ? JSON.parse(raw) : null;
    return draft && Array.isArray(draft.attributes) ? draft : emptyDraft();
  } catch {
    return emptyDraft();
  }
}

export function saveDraft(draft) {
  try {
    if (draft) localStorage.setItem(DRAFT_KEY, JSON.stringify(draft));
    else localStorage.removeItem(DRAFT_KEY);
  } catch {
    return;
  }
}
