import { useEffect, useMemo, useRef, useState } from 'react';
import BuildSchemaModal from '@/components/BuildSchemaModal';
import LoadPapersModal from '@/components/LoadPapersModal';
import { humanize } from '@/lib/humanize';
import {
  KIND_LABELS,
  ROLES,
  USES,
  applyMapping,
  extractAttributes,
  loadUploadedSchema,
  mappingFromAnnotations,
  saveUploadedSchema,
  suggestMapping,
  toggleUse,
  validateSchema,
} from '@/lib/schemaMapping';
import { parseReviewFile, restartSite } from '@/lib/review';
import { saveWorkspace } from '@/lib/workspace';

const VIEWS = [...new Set(USES.map((u) => u.view))];

function downloadJson(data, fileName) {
  const blob = new Blob([`${JSON.stringify(data, null, 2)}\n`], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

const attributeLabel = (a) => humanize(a.name);

/**
 * The schema and how the views use its attributes. Shows the published
 * schema, or, while the visitor's own review is shown (`review`), the
 * review's schema. An uploaded or built schema can be filled out here and
 * used to load papers into a review.
 */
export default function SchemaPanel({ schemaUrl, schemaFile, review = null }) {
  const [publishedSchema, setPublishedSchema] = useState(null);
  const defaultSchema = review ? review.schema : publishedSchema;
  const [uploaded, setUploaded] = useState(loadUploadedSchema);
  const [error, setError] = useState(null);
  const [showAll, setShowAll] = useState(false);
  const [building, setBuilding] = useState(false);
  const [loading, setLoading] = useState(false);
  const fileRef = useRef(null);
  const reviewFileRef = useRef(null);

  useEffect(() => {
    fetch(schemaUrl).then((r) => (r.ok ? r.json() : null)).then(setPublishedSchema).catch(() => setPublishedSchema(null));
  }, [schemaUrl]);

  useEffect(() => {
    saveUploadedSchema(uploaded);
  }, [uploaded]);

  const schema = uploaded ? uploaded.schema : defaultSchema;
  const attributes = useMemo(() => (schema ? extractAttributes(schema) : []), [schema]);
  const mapping = uploaded ? uploaded.mapping : mappingFromAnnotations(attributes);
  const editable = Boolean(uploaded);

  const roleOf = (path) => ROLES.find((r) => mapping.roles[r.key] === path);
  const isUsed = (a) => Boolean(roleOf(a.path)) || (mapping.uses[a.path]?.size || 0) > 0;
  const listed = showAll ? attributes : attributes.filter(isUsed);
  const hiddenCount = attributes.length - attributes.filter(isUsed).length;

  const handleFile = async (file) => {
    if (!file) return;
    setError(null);
    let parsed;
    try {
      parsed = JSON.parse(await file.text());
    } catch {
      setError(`${file.name} is not valid JSON.`);
      return;
    }
    const problem = validateSchema(parsed);
    if (problem) {
      setError(`${file.name}: ${problem}`);
      return;
    }
    const attrs = extractAttributes(parsed);
    setUploaded({ fileName: file.name, schema: parsed, mapping: suggestMapping(attrs) });
    setShowAll(true);
  };

  const setRole = (key, path) => setUploaded((u) => ({ ...u, mapping: { ...u.mapping, roles: { ...u.mapping.roles, [key]: path || undefined } } }));
  const toggle = (path, useKey) => setUploaded((u) => ({ ...u, mapping: toggleUse(u.mapping, path, useKey) }));

  const missingRoles = ROLES.filter((r) => !mapping.roles[r.key]);
  const hasDefaultTile = Object.values(mapping.uses).some((set) => set.has('overview.defaultTile'));

  const applyBuilt = (built, fileName) => {
    setError(null);
    setUploaded({ fileName, schema: built, mapping: mappingFromAnnotations(extractAttributes(built)) });
    setShowAll(true);
    setBuilding(false);
  };

  // A downloaded review (Download in the review bar) becomes the stored
  // review again and is shown.
  const openReviewFile = async (file) => {
    if (!file) return;
    setError(null);
    const restored = parseReviewFile(await file.text());
    if (!restored) {
      setError(`${file.name} is not a review downloaded from Ariadne Lit.`);
      return;
    }
    if (!window.confirm(`Open the review "${restored.name}" (${restored.papers.length} papers)? It replaces the review stored in this browser, if there is one.`)) return;
    try {
      await saveWorkspace({ ...restored, active: true });
      restartSite();
    } catch (e) {
      setError(`Could not open the review: ${e.message}`);
    }
  };

  const filledSchema = () => applyMapping(uploaded.schema, attributes, mapping, publishedSchema?.['x-ariadne'] || null);
  const downloadFilled = () => downloadJson(filledSchema(), uploaded.fileName.replace(/\.json$/i, '') + '.ariadne.json');
  // The review uses the schema shown: the filled uploaded or built one, or the default.
  const reviewSchema = () => (editable ? filledSchema() : defaultSchema);

  return (
    <div className="schema-panel">
      <div className="schema-panel__actions">
        {editable ? (
          <button type="button" className="btn btn--primary btn--sm" onClick={downloadFilled} disabled={missingRoles.length > 0}
            title={missingRoles.length ? `Choose ${missingRoles.map((r) => r.label).join(' and ')} first` : undefined}>
            Download Filled Schema
          </button>
        ) : (
          review ? (
            <button type="button" className="btn btn--secondary btn--sm"
              onClick={() => downloadJson(review.schema, `${(review.name || 'my-review').replace(/[^\w-]+/g, '-')}.schema.json`)}>
              Download Schema (JSON)
            </button>
          ) : (
            <a className="btn btn--secondary btn--sm" href={schemaUrl} download={schemaFile}>
              Download Schema (JSON)
            </a>
          )
        )}
        <button type="button" className="btn btn--secondary btn--sm" onClick={() => fileRef.current?.click()}>
          {editable ? 'Upload Another Schema' : 'Upload Schema'}
        </button>
        <button type="button" className="btn btn--primary btn--sm" onClick={() => setBuilding(true)}>
          + Build Schema
        </button>
        <button type="button" className="btn btn--secondary btn--sm" onClick={() => setLoading(true)}
          disabled={!schema || missingRoles.length > 0}
          title={missingRoles.length ? `Choose ${missingRoles.map((r) => r.label).join(' and ')} first` : 'Load papers into your own review, coded against this schema'}>
          Load Papers…
        </button>
        {editable && (
          <button type="button" className="btn btn--ghost btn--sm" onClick={() => { setUploaded(null); setError(null); setShowAll(false); }}>
            {review ? 'Return to the Schema of Your Review' : 'Return to Default Schema'}
          </button>
        )}
        <button type="button" className="btn btn--ghost btn--sm" onClick={() => reviewFileRef.current?.click()}
          title="Open a review saved with Download in the review bar">
          Open Review File…
        </button>
        <input ref={reviewFileRef} type="file" accept=".json,application/json" hidden
          onChange={(e) => { openReviewFile(e.target.files?.[0]); e.target.value = ''; }} />
        <input ref={fileRef} type="file" accept=".json,application/json,application/schema+json" hidden
          onChange={(e) => { handleFile(e.target.files?.[0]); e.target.value = ''; }} />
      </div>

      {error && <p className="add-paper__error" role="alert">{error}</p>}

      {loading && <LoadPapersModal schema={reviewSchema()} onClose={() => setLoading(false)} />}

      {building && (
        <BuildSchemaModal
          meta={publishedSchema?.['x-ariadne'] || null}
          onClose={() => setBuilding(false)}
          onDownload={(built, fileName) => downloadJson(built, fileName)}
          onUse={applyBuilt}
        />
      )}

      <p className="about-text about-text--muted schema-panel__status">
        {editable
          ? `Showing your schema ${uploaded.fileName}. Choose how each attribute is used, then download the filled schema, or start your own review with it: Load Papers. It is kept in this browser only.`
          : review
            ? `Showing the schema of your review ${review.name} and how each view uses its attributes. Load Papers adds papers to your review.`
            : 'Showing the default schema and how each view uses its attributes. Build or upload your own schema to start your own review, or use Load Papers with this one.'}
      </p>

      {schema && (
        <>
          <div className="schema-panel__roles">
            {ROLES.map((role) => {
              const options = attributes.filter(role.fits);
              return (
                <label key={role.key} className="ax-field">
                  <span className="ax-field__label">{role.label}</span>
                  <select className="ax-select" value={mapping.roles[role.key] || ''} disabled={!editable}
                    onChange={(e) => setRole(role.key, e.target.value)}>
                    <option value="">Choose an attribute…</option>
                    {options.map((a) => <option key={a.path} value={a.path}>{attributeLabel(a)} ({a.path})</option>)}
                  </select>
                  <span className="schema-panel__hint">{role.description}</span>
                </label>
              );
            })}
          </div>

          {editable && (missingRoles.length > 0 || !hasDefaultTile) && (
            <p className="add-paper__warning">
              {missingRoles.length > 0 && `Choose the attribute for ${missingRoles.map((r) => r.label).join(' and ')}. `}
              {!hasDefaultTile && 'Mark one attribute as the default tiles on Overview.'}
            </p>
          )}

          <div className="ax-table-wrap schema-panel__table-wrap">
            <table className="ax-table schema-panel__table">
              <thead>
                <tr>
                  <th rowSpan={2} scope="col">Attribute</th>
                  <th rowSpan={2} scope="col">Type</th>
                  {VIEWS.map((view) => (
                    <th key={view} colSpan={USES.filter((u) => u.view === view).length} scope="colgroup" className="schema-panel__view">{view}</th>
                  ))}
                </tr>
                <tr>
                  {USES.map((u) => <th key={u.key} scope="col" className="schema-panel__use">{u.label}</th>)}
                </tr>
              </thead>
              <tbody>
                {listed.map((a) => {
                  const role = roleOf(a.path);
                  return (
                    <tr key={a.path}>
                      <th scope="row" title={a.description || a.path}>
                        <span className="schema-panel__attr">
                          <span>{attributeLabel(a)}</span>
                          <span className="schema-panel__path">{a.path}</span>
                        </span>
                      </th>
                      <td className="schema-panel__kind">
                        {KIND_LABELS[a.kind]}
                        {a.values?.length ? ` · ${a.values.length} values` : ''}
                      </td>
                      {role ? (
                        <td colSpan={USES.length} className="schema-panel__role">Fixed role ({role.label}): {role.description.replace(/^Fixed: /, '')}</td>
                      ) : (
                        USES.map((u) => {
                          const checked = mapping.uses[a.path]?.has(u.key) || false;
                          const fits = u.fits(a);
                          return (
                            <td key={u.key} className="schema-panel__cell">
                              {editable ? (
                                <input type="checkbox" checked={checked} disabled={!fits && !checked}
                                  onChange={() => toggle(a.path, u.key)}
                                  aria-label={`${attributeLabel(a)}: ${u.view}, ${u.label}`}
                                  title={!fits ? `Not suitable for ${u.label}` : u.single ? 'Only one attribute can have this' : undefined} />
                              ) : (
                                checked && <span className="schema-panel__mark" aria-label={`${u.view}, ${u.label}`}>✓</span>
                              )}
                            </td>
                          );
                        })
                      )}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          {hiddenCount > 0 && (
            <label className="graph-controls__toggle schema-panel__toggle">
              <input type="checkbox" checked={showAll} onChange={(e) => setShowAll(e.target.checked)} />
              <span>Show the {hiddenCount} attributes no view uses</span>
            </label>
          )}
        </>
      )}
    </div>
  );
}
